fn select_aether_track_for_action(ui: &MainWindow, id: i32) {
    if id > 0 && ui.get_selected_track_index() != id {
        ui.set_selected_track_index(id);
        ui.invoke_track_select(id - 1);
    }
}

/// 由 pitch 范围算 16 行窗口的 `roll_base_pitch`：
/// 跨度 < 16 半音 ⇒ 全部可见（上下留白 ≤2 行）；≥ 16 ⇒ 居中（两端各露一半）。
fn roll_base_for_pitch_range(lo: u8, hi: u8) -> u8 {
    let lane_count = crate::bridge::PITCH_LANE_COUNT as u8;
    let span = hi.saturating_sub(lo);
    let base = if span < lane_count {
        lo.saturating_sub((lane_count - 1 - span).min(2))
    } else {
        lo.saturating_add(span / 2).saturating_sub(lane_count / 2)
    };
    // u8 天然 >= 0；只需钳上界（base+15 不得超过 127）。
    base.min(127 - (lane_count - 1))
}

/// 由片段起始 tick 算卷帘横向 scroll（片段起点留 16px 边距）。
fn roll_scroll_for_tick(ui: &MainWindow, start_tick: u64) -> f32 {
    let tpp = roll_ticks_per_pixel(ui).max(1);
    let px = crate::bridge::tick_to_px(start_tick, tpp)
        .map(|v| v as f32)
        .unwrap_or(0.0);
    (px - 16.0).max(0.0)
}

/// 把卷帘音高窗口取景到 `[lo, hi]`（**唯一**的取景公式落点：选轨联动与
/// `apply_view` 的作用域取景都经这里，⛔ 不许出现第二处
/// `apply_roll_pitch_range(roll_base_for_pitch_range(..))`）。
fn frame_roll_pitch_to_range(ui: &MainWindow, lo: u8, hi: u8) {
    apply_roll_pitch_range(ui, roll_base_for_pitch_range(lo, hi));
}

/// 当前卷帘作用域的**取景键 + 音高范围**：作用域优先级与 `apply_view` 的音符
/// 收窄同一条（选中片段 > 选中轨 > 全部）。范围取该作用域**全部**音符（不按
/// 时间窗裁剪——取景是「这条轨/这个片段的音都在哪」，与横向滚动无关）。
fn roll_scope_key_and_range(ui: &MainWindow, view: &ViewState) -> (String, Option<(u8, u8)>) {
    let (key, allowed): (String, Option<std::collections::BTreeSet<&str>>) =
        if let Some(scope) = roll_scope(ui, view) {
            (
                format!("clip:{scope}"),
                Some(std::collections::BTreeSet::from([scope])),
            )
        } else if let Some(track_id) = view.selected_track.as_deref() {
            match view.tracks.iter().position(|track| track.id == track_id) {
                Some(index) => {
                    let allowed = view
                        .clips
                        .iter()
                        .filter(|clip| clip.track_index == index)
                        .map(|clip| clip.clip_id.as_str())
                        .collect();
                    (format!("track:{track_id}"), Some(allowed))
                }
                None => ("all".to_string(), None),
            }
        } else {
            ("all".to_string(), None)
        };
    let mut lo: Option<u8> = None;
    let mut hi: Option<u8> = None;
    for note in &view.notes {
        if allowed
            .as_ref()
            .is_some_and(|set| !set.contains(note.clip_id.as_str()))
        {
            continue;
        }
        lo = Some(lo.map_or(note.pitch, |x| x.min(note.pitch)));
        hi = Some(hi.map_or(note.pitch, |x| x.max(note.pitch)));
    }
    (key, lo.zip(hi))
}

/// ⭐ **作用域变了才重取景**（2026-11-23 Wang 实证）：此前音高窗口是粘性
/// 状态——只有「点轨道头选一条 MIDI 轨」一条路（[`roll_focus_on_track`]）会
/// 改它；打开工程、选音频轨、选轨后又滚轮平移过，都让窗口停在历史位置。
/// 后果：《雨声太吵》贝斯/鼓音高 28–50 在默认窗口 60–75 之外 ⇒ 卷帘全空；
/// 《失语》全音频轨无一物可取景，窗口停在 C1 一带，看起来与选中轨毫无关系。
///
/// 现行口径（照 Wang 定：按轨道内容显示、音符居中、不固定范围）：
/// `apply_view` 每次先算当前作用域键，与 `roll-framed-scope` 比——
/// - 变了 ⇒ 按新作用域的音高范围取景（公式同选轨联动）；作用域无音符
///   （音频轨/空轨）⇒ 回中性窗口（默认 base），⛔ 不留上一作用域的陈旧窗口；
/// - 没变 ⇒ 一位不动（滚轮/八度平移的手动窗口在同一作用域内保持）。
fn reframe_roll_pitch_if_scope_changed(ui: &MainWindow, view: &ViewState) {
    let (key, range) = roll_scope_key_and_range(ui, view);
    if ui.get_roll_framed_scope().as_str() == key {
        return;
    }
    ui.set_roll_framed_scope(key.into());
    match range {
        Some((lo, hi)) => frame_roll_pitch_to_range(ui, lo, hi),
        None => {
            apply_roll_pitch_range(ui, crate::bridge::PITCH_LANE_BASE);
        }
    }
}

/// 选轨时的**卷帘精准联动**：把卷帘横向滚到该轨**首个音符**（⛔ 不是摆放起点 —— 摆放可以从 0 起而音符在很后面），纵向把
/// `roll_base_pitch` 对齐到该轨音符范围（`roll-min-pitch` 由随后的
/// `apply_view` 按 base 推出）。
///
/// - 跨度 < 16 半音 ⇒ 全部音符落在 16 行窗口内（上下各留 ≤2 行 padding）。
/// - 跨度 ≥ 16 ⇒ 居中（最低/最高各露一半），并如实提示可纵向滚动。
/// - 音频轨 / 空轨（无 MIDI 音符）⇒ 一位不动。
///
/// 返回 `true` = 横向滚动被改过（调用方应重读 `roll_scroll_x` 再 `apply_view`）。
/// 某条轨**首个音符**的绝对 tick（摆放起点 ＋ 音符片段内 tick 的最小值）。
///
/// ⭐ T-FIX-193 D4 与 T-FIX-2392（打开工程）**共用这一份口径**：横向落点取首个
/// 音符，⛔ 不是摆放起点 —— 摆放可以从 0 起而首个音符在很后面（尼龙·扫弦 start=0、
/// 首音符 80636；《回头路》鼓刷军鼓首音符 89280）。
///
/// 无 MIDI 音符（音频轨 / 空轨 / 悬空片段引用）⇒ `None`；调用方按 0 处理，不 panic。
fn first_note_tick_on_track(
    project: &yeban_model::YebanProjectV1,
    track_id: yeban_model::EntityId,
) -> Option<u64> {
    let track = project.tracks.get(&track_id)?;
    let mut first: Option<u64> = None;
    for placement in track.clips.values() {
        let Some(entry) = project.clip_pool.get(&placement.clip_id) else {
            continue;
        };
        let yeban_model::project::ClipContent::Midi { notes } = &entry.content else {
            continue;
        };
        for note in notes.values() {
            let absolute = placement.start_tick.saturating_add(note.start_tick);
            first = Some(first.map_or(absolute, |tick| tick.min(absolute)));
        }
    }
    first
}

fn roll_focus_on_track(
    ui: &MainWindow,
    project: &yeban_model::YebanProjectV1,
    track_id: &str,
) -> bool {
    let Ok(tid) = track_id.parse::<yeban_model::EntityId>() else {
        return false;
    };
    let Some(track) = project.tracks.get(&tid) else {
        return false;
    };
    // ⭐ T-FIX-193 D4：横向落点取**首个音符**（[`first_note_tick_on_track`]），
    //    ⛔ 不是摆放起点 —— 摆放可以从 0 起而音符在很后面。
    let mut lo: Option<u8> = None;
    let mut hi: Option<u8> = None;
    for placement in track.clips.values() {
        let Some(entry) = project.clip_pool.get(&placement.clip_id) else {
            continue;
        };
        let yeban_model::project::ClipContent::Midi { notes } = &entry.content else {
            continue;
        };
        if notes.is_empty() {
            continue;
        }
        for note in notes.values() {
            lo = Some(lo.map_or(note.pitch, |x| x.min(note.pitch)));
            hi = Some(hi.map_or(note.pitch, |x| x.max(note.pitch)));
        }
    }
    let (Some(lo), Some(hi)) = (lo, hi) else {
        return false;
    };
    let Some(start_tick) = first_note_tick_on_track(project, tid) else {
        return false;
    };
    let lane_count = crate::bridge::PITCH_LANE_COUNT as u8;
    let span = hi.saturating_sub(lo);
    frame_roll_pitch_to_range(ui, lo, hi);
    if span >= lane_count {
        ui.set_module_status(
            format!(
                "卷帘已对准该轨音区（{lo}–{hi}，跨 {span} 半音，超出 16 行窗口，可纵向滚动查看）"
            )
            .into(),
        );
        ui.set_module_status_succeeded(true);
    }
    ui.set_roll_scroll_x(roll_scroll_for_tick(ui, start_tick));
    true
}

/// 选片段时的**横向精准联动**：滚到该片段起点。
///
/// 音域由 `on_clip_select` 里的 `invoke_track_select`（按轨）负责 ——
/// 这里**只做横向**，⛔ 不重复改 base：两点原因
/// 1. 与按轨口径只留一份（避免"点片段音域更窄"这类第二真相源）；
/// 2. 改 base 会破坏依赖"默认 base=60"的既有卷帘判据
///    （实测：`aether_piano_roll` 的 lane15=C4 断言因此红）。
///
/// 返回 `true` = 横向滚动被改过。
fn roll_focus_on_clip(
    ui: &MainWindow,
    project: &yeban_model::YebanProjectV1,
    clip_ulid: &str,
) -> bool {
    let Some((_, _, placement)) = clip_placement_for(project, clip_ulid) else {
        return false;
    };
    ui.set_roll_scroll_x(roll_scroll_for_tick(ui, placement.start_tick));
    true
}

fn roll_base_pitch(ui: &MainWindow) -> u8 {
    let raw = ui.get_roll_base_pitch();
    u8::try_from(raw.clamp(0, 112)).unwrap_or(crate::bridge::PITCH_LANE_BASE)
}

fn apply_roll_pitch_range(ui: &MainWindow, next: u8) -> String {
    ui.set_roll_base_pitch(i32::from(next));
    let top_pitch = next.saturating_add((crate::bridge::PITCH_LANE_COUNT - 1) as u8);
    let range_label = format!("{} – {}", midi_pitch_name(next), midi_pitch_name(top_pitch));
    ui.set_roll_pitch_range_label(range_label.clone().into());
    let mut labels = Vec::with_capacity(crate::bridge::PITCH_LANE_COUNT as usize);
    let mut whites = Vec::with_capacity(crate::bridge::PITCH_LANE_COUNT as usize);
    for lane in 0..crate::bridge::PITCH_LANE_COUNT {
        if let Some(p) = crate::bridge::pitch_for_lane_with_base(lane, next) {
            labels.push(slint::SharedString::from(roll_key_sharp_label(p)));
            whites.push(is_white_midi_key(p));
        }
    }
    ui.set_roll_lane_key_labels(slint::ModelRc::new(slint::VecModel::from(labels)));
    ui.set_roll_lane_is_white(slint::ModelRc::new(slint::VecModel::from(whites)));
    range_label
}

fn roll_key_sharp_label(pitch: u8) -> String {
    const NAMES: [&str; 12] = [
        "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B",
    ];
    let octave = i32::from(pitch / 12) - 1;
    format!("{}{}", NAMES[usize::from(pitch % 12)], octave)
}

fn is_white_midi_key(pitch: u8) -> bool {
    matches!(pitch % 12, 0 | 2 | 4 | 5 | 7 | 9 | 11)
}

fn track_audibility_warning(
    project: &yeban_model::YebanProjectV1,
    track_id: yeban_model::EntityId,
) -> Option<&'static str> {
    let track = project.tracks.get(&track_id)?;
    let any_solo = project
        .tracks
        .values()
        .any(|t| t.id != project.master_bus_track_id && t.solo);
    if any_solo && !track.solo && !track.solo_safe {
        return Some("其它轨道正在 Solo，当前轨已静音");
    }
    if track.mute {
        return Some("当前轨道处于静音 (Mute)");
    }
    if track.volume_db <= -60.0 {
        return Some("当前轨道推子已拉至最小 (-∞ dB)");
    }
    None
}

fn track_can_play_pitches(track: &yeban_model::project::TrackV3, pitches: &[u8]) -> bool {
    if track.mute || track.volume_db <= -60.0 {
        return false;
    }
    if let Some(drums) = yeban_engine::drums::DrumsParams::from_devices(&track.devices) {
        return !pitches.is_empty()
            && pitches
                .iter()
                .any(|p| drums.notes().voice_for(*p).is_some());
    }
    true
}

fn track_audible_for_pitches(
    project: &yeban_model::YebanProjectV1,
    track: &yeban_model::project::TrackV3,
    pitches: &[u8],
    any_solo: bool,
) -> bool {
    if track.id == project.master_bus_track_id {
        return false;
    }
    if any_solo && !track.solo && !track.solo_safe {
        return false;
    }
    track_can_play_pitches(track, pitches)
}

fn publish_project_for_audition(port: &UndoPort, engine: &Rc<RefCell<EngineHost>>) {
    let mark = crate::engine_host::EditMark::from_display(&port.display());
    let should = {
        let host = engine.borrow();
        host.has_engine() && host.should_publish(mark)
    };
    if should && let Some(project) = port.try_project() {
        // ⭐ P0-7：试听发布与主心跳用**同一个**端口标记 ⇒ 本跳若因解码转后台
        //    而延后（`PublishOutcome::Deferred`），主心跳会在后续跳里以同一标记
        //    完成发布，试听目标随之生效（`let _` 丢弃结局是既有口径，不变）。
        let _ = engine.borrow_mut().publish_project(&project, mark);
    }
}

/// 解析试听目标轨并补齐最小可发声链路：
/// 1. 空工程（0 条非主总线轨）自动建一条内置合成器 MIDI 轨并选中；
/// 2. 未静音 MIDI 轨缺少乐器/路由时自动安装 `Yeban PolySynth` 并立即发布给引擎；
/// 3. 明确 `mute == true` 的轨道保留“静音”提示（供测试与用户感知）；
/// 4. Audio / Aux / Master 轨或被他人 Solo / 鼓机未映射键位阻断时，优先回落到当前可听的 MIDI 合成器轨（无任何 MIDI 轨时自动建一条）。
fn resolve_and_prepare_audition_target(
    ui: &MainWindow,
    port: &UndoPort,
    engine: &Rc<RefCell<EngineHost>>,
    pitches: &[u8],
) -> Option<(yeban_model::EntityId, Option<&'static str>)> {
    let mut project = port.try_project()?;
    let selected = selected_track_id(ui);
    if crate::bridge::display_track(&project, selected.as_deref()).is_none()
        && let Ok(ops) =
            crate::bridge::track_create_ops(&project, crate::bridge::NewTrackKind::Midi)
    {
        let created_id = ops.iter().find_map(|op| match op {
            yeban_model::ops::Op::AddTrack { track } => Some(track.id),
            _ => None,
        });
        if port
            .commit_ops(now_ms(), "piano-roll: auto create midi track", ops)
            .is_ok()
        {
            if let Some(tid) = created_id {
                ui.set_selected_track_id(tid.to_canonical_string().into());
            }
            refresh_undo_window(ui, port, true);
            project = port.try_project()?;
        }
    }

    let displayed = crate::bridge::display_track(&project, selected_track_id(ui).as_deref());
    if let Some(track) = displayed {
        if track.kind == yeban_model::project::TrackKind::Midi {
            if !track.mute {
                let ops = ensure_track_instrument_ops(&project, track.id);
                if !ops.is_empty()
                    && port
                        .commit_ops(now_ms(), "piano-roll: auto install instrument", ops)
                        .is_ok()
                {
                    refresh_undo_window(ui, port, true);
                    project = port.try_project()?;
                }
            }
        } else {
            let any_solo = project
                .tracks
                .values()
                .any(|t| t.id != project.master_bus_track_id && t.solo);
            let existing_midi = project
                .tracks
                .values()
                .filter(|t| {
                    t.id != project.master_bus_track_id
                        && t.kind == yeban_model::project::TrackKind::Midi
                })
                .collect::<Vec<_>>();
            let fallback_candidate = existing_midi
                .iter()
                .copied()
                .find(|t| {
                    track_audible_for_pitches(&project, t, pitches, any_solo)
                        && yeban_engine::drums::DrumsParams::from_devices(&t.devices).is_none()
                })
                .or_else(|| {
                    existing_midi
                        .iter()
                        .copied()
                        .find(|t| track_audible_for_pitches(&project, t, pitches, any_solo))
                })
                .or_else(|| {
                    existing_midi.iter().copied().find(|t| {
                        track_can_play_pitches(t, pitches)
                            && yeban_engine::drums::DrumsParams::from_devices(&t.devices).is_none()
                    })
                })
                .or_else(|| {
                    existing_midi
                        .iter()
                        .copied()
                        .find(|t| track_can_play_pitches(t, pitches))
                });
            if let Some(candidate) = fallback_candidate {
                let ops = ensure_track_instrument_ops(&project, candidate.id);
                if !ops.is_empty()
                    && port
                        .commit_ops(now_ms(), "piano-roll: auto install instrument", ops)
                        .is_ok()
                {
                    refresh_undo_window(ui, port, true);
                    project = port.try_project()?;
                }
            } else if let Ok(ops) =
                crate::bridge::track_create_ops(&project, crate::bridge::NewTrackKind::Midi)
            {
                let created_id = ops.iter().find_map(|op| match op {
                    yeban_model::ops::Op::AddTrack { track } => Some(track.id),
                    _ => None,
                });
                if port
                    .commit_ops(now_ms(), "piano-roll: auto create midi track", ops)
                    .is_ok()
                {
                    if let Some(tid) = created_id {
                        ui.set_selected_track_id(tid.to_canonical_string().into());
                    }
                    refresh_undo_window(ui, port, true);
                    project = port.try_project()?;
                }
            }
        }
    }

    publish_project_for_audition(port, engine);

    let any_solo = project
        .tracks
        .values()
        .any(|t| t.id != project.master_bus_track_id && t.solo);
    let track = crate::bridge::display_track(&project, selected_track_id(ui).as_deref())
        .or_else(|| {
            project
                .tracks
                .values()
                .find(|t| t.id != project.master_bus_track_id)
        })
        .or_else(|| project.tracks.values().next())?;

    if track.kind == yeban_model::project::TrackKind::Midi {
        if track.mute {
            return Some((track.id, Some("当前轨道处于静音 (Mute)")));
        }
        if track.volume_db <= -60.0 {
            return Some((track.id, Some("当前轨道推子已拉至最小 (-∞ dB)")));
        }
        if track_audible_for_pitches(&project, track, pitches, any_solo) {
            return Some((track.id, None));
        }
        if let Some(fallback) = project.tracks.values().find(|candidate| {
            candidate.id != project.master_bus_track_id
                && candidate.kind == yeban_model::project::TrackKind::Midi
                && track_audible_for_pitches(&project, candidate, pitches, any_solo)
                && yeban_engine::drums::DrumsParams::from_devices(&candidate.devices).is_none()
        }) {
            return Some((fallback.id, None));
        }
        if let Some(fallback) = project.tracks.values().find(|candidate| {
            candidate.id != project.master_bus_track_id
                && candidate.kind == yeban_model::project::TrackKind::Midi
                && track_audible_for_pitches(&project, candidate, pitches, any_solo)
        }) {
            return Some((fallback.id, None));
        }
        return Some((track.id, track_audibility_warning(&project, track.id)));
    }

    if let Some(midi_track) = project
        .tracks
        .values()
        .find(|candidate| {
            candidate.id != project.master_bus_track_id
                && candidate.kind == yeban_model::project::TrackKind::Midi
                && track_audible_for_pitches(&project, candidate, pitches, any_solo)
                && yeban_engine::drums::DrumsParams::from_devices(&candidate.devices).is_none()
        })
        .or_else(|| {
            project.tracks.values().find(|candidate| {
                candidate.id != project.master_bus_track_id
                    && candidate.kind == yeban_model::project::TrackKind::Midi
                    && track_audible_for_pitches(&project, candidate, pitches, any_solo)
            })
        })
        .or_else(|| {
            project.tracks.values().find(|candidate| {
                candidate.id != project.master_bus_track_id
                    && candidate.kind == yeban_model::project::TrackKind::Midi
                    && track_can_play_pitches(candidate, pitches)
                    && yeban_engine::drums::DrumsParams::from_devices(&candidate.devices).is_none()
            })
        })
        .or_else(|| {
            project.tracks.values().find(|candidate| {
                candidate.id != project.master_bus_track_id
                    && candidate.kind == yeban_model::project::TrackKind::Midi
                    && track_can_play_pitches(candidate, pitches)
            })
        })
    {
        return Some((midi_track.id, None));
    }

    if let Some(any_midi) = project
        .tracks
        .values()
        .find(|candidate| candidate.kind == yeban_model::project::TrackKind::Midi)
    {
        return Some((any_midi.id, track_audibility_warning(&project, any_midi.id)));
    }
    Some((track.id, track_audibility_warning(&project, track.id)))
}

fn dispatch_aether_audition(
    ui: &MainWindow,
    engine: &Rc<RefCell<EngineHost>>,
    track: yeban_model::EntityId,
    pitches: &[u8],
    velocity: u8,
    status_prefix: &str,
    audibility_warning: Option<&'static str>,
) {
    if !engine.borrow().has_engine() {
        ui.set_module_status("试听: 引擎未接线（工程可继续编辑）".into());
        ui.set_module_status_succeeded(false);
        return;
    }
    let on_events: Vec<yeban_engine::ring::EngineEvent> = pitches
        .iter()
        .copied()
        .map(|pitch| yeban_engine::ring::EngineEvent::NoteOn {
            track,
            pitch,
            velocity,
        })
        .collect();
    let off_events: Vec<yeban_engine::ring::EngineEvent> = pitches
        .iter()
        .copied()
        .map(|pitch| yeban_engine::ring::EngineEvent::NoteOff { track, pitch })
        .collect();
    let (count, device_active) = {
        let mut host = engine.borrow_mut();
        let active = host.device_active();
        let written = host.send_engine_events(&on_events);
        if !active {
            let _ = host.pump(4);
            let _ = host.send_engine_events(&off_events);
        }
        (written, active)
    };
    if device_active {
        let engine_weak = Rc::downgrade(engine);
        slint::Timer::single_shot(std::time::Duration::from_millis(260), move || {
            if let Some(host_rc) = engine_weak.upgrade() {
                let _ = host_rc.borrow_mut().send_engine_events(&off_events);
            }
        });
    }
    let msg = match audibility_warning {
        Some(warn) => {
            ui.set_roll_edit_status(format!("试听提示: {warn}").into());
            format!("{status_prefix}: 引擎事件通道已调用, 写入 {count} 条（提示: {warn}）")
        }
        None => {
            if ui.get_roll_edit_status().as_str().starts_with("试听提示:") {
                ui.set_roll_edit_status("".into());
            }
            format!("{status_prefix}: 引擎事件通道已调用, 写入 {count} 条")
        }
    };
    ui.set_module_status(msg.into());
    ui.set_module_status_succeeded(true);
}

fn dispatch_aether_command(ui: &MainWindow, cmd: &str) {
    match cmd {
        "file-new" => ui.invoke_new_project(),
        "file-new-from-template" => ui.invoke_new_from_template(),
        "file-open" => ui.invoke_open_project(),
        "file-save" => ui.invoke_save_project(),
        "file-save-as" => ui.invoke_save_project_as(),
        "file-save-as-template" => ui.invoke_save_as_template(),
        "open-export-wav" => ui.invoke_open_export_wav(),
        "open-audio-settings" => ui.invoke_open_audio_settings(),
        // ⛔ 这里**不再有** `export-stems` 臂：真实入口在 `on_command_execute` 里先命中
        // （见 `stems_output_dir` 与 `crate::export_stems::export_stems`）。旧的
        // 「打开 WAV 面板 + 提示请用 CLI」分支已删除——留着会让下一个人误判成"还没修"。
        "export-midi" => ui.invoke_export_midi(),
        "import-midi" => ui.invoke_import_midi(),
        "import-audio" => ui.invoke_import_audio(),
        "load-sfz" => ui.invoke_load_sfz(),
        "record-wav" => ui.invoke_record_wav(),
        "undo-step" => ui.invoke_undo_step(),
        "redo-step" => ui.invoke_redo_step(),
        "toggle-undo-tree" => ui.invoke_toggle_undo_tree(),
        "open-quantize" => ui.invoke_open_quantize(),
        "open-otcp" => ui.invoke_open_otcp(),
        "open-phase-align" => ui.invoke_open_phase_align(),
        "open-humanize" => ui.invoke_open_humanize(),
        "open-drum-gen" => ui.invoke_open_drum_gen(),
        "open-sound-library" => ui.invoke_open_sound_library(),
        "toggle-musical-pr" => ui.invoke_open_musical_pr(),
        "track-add-midi" => ui.invoke_track_create_midi(),
        "track-add-audio" => ui.invoke_track_create_audio(),
        "track-add-aux" | "track-add-bus" => ui.invoke_track_create_aux(),
        "track-delete" => ui.invoke_track_delete(),
        "new-midi-clip" => ui.invoke_clip_create(),
        "insert-eq" => ui.invoke_device_insert_eq(),
        "insert-reverb" => ui.invoke_device_insert_reverb(),
        "insert-compressor" => {
            let id = ui.get_selected_track_index().max(1);
            ui.invoke_track_instrument_change(id, "fx:compressor".into());
        }
        "normalize-heights" | "track-equal-heights" => ui.invoke_normalize_track_heights(),
        "track-toggle-headers-side" => {
            let theme = ui.global::<crate::ui::Theme<'_>>();
            let next = !theme.get_track_headers_on_right();
            theme.set_track_headers_on_right(next);
            update_toast(
                ui,
                if next {
                    "[视图] 轨道头已切换到右侧"
                } else {
                    "[视图] 轨道头已切换到左侧"
                },
            );
        }
        "toggle-chord-lane" => {
            let next = !ui.get_show_chord_track();
            ui.set_show_chord_track(next);
            update_toast(
                ui,
                if next {
                    "[编曲] 已显示和弦参考轨"
                } else {
                    "[编曲] 已隐藏和弦参考轨"
                },
            );
        }
        "transport-play" => ui.invoke_toggle_play(),
        "transport-stop" => ui.invoke_stop(),
        "transport-rewind" => {
            ui.invoke_stop();
            update_toast(ui, "[走带] 播放头已归零至 001.01.000");
        }
        "transport-loop" => {
            ui.invoke_key_action("c".into(), false, false, false, false);
        }
        "transport-metronome" => ui.invoke_toggle_metronome(),
        // T-FIX-157：Scroll in Play 模式切换（播放头钉中央、逐跳平滑滚动）。
        // 翻转 MainWindow 属性（tick 每跳同步到跟随状态机），并落盘持久化。
        "transport-scroll-in-play" | "toggle-scroll-in-play" => {
            let next = !ui.get_scroll_in_play();
            ui.set_scroll_in_play(next);
            crate::settings::save_scroll_in_play(next);
            update_toast(
                ui,
                if next {
                    "[走带] 滚动跟随：Scroll in Play（播放头居中）"
                } else {
                    "[走带] 滚动跟随：经典 Catch（播放头贴左缘）"
                },
            );
            // 写回失败 ⇒ 错误级常驻提示（T-FIX-299）：放在 toast 之后，
            // 让警告成为本次手势的最后一条可见反馈。
            report_pending_settings_warnings(ui);
        }
        // 预备拍开关（清单 P1-8）：走与 Ctrl+Alt+D 完全相同的链
        // （解析表 -> apply_action），不另写一份 toggle 逻辑
        // （Action::ToggleCountIn 的唯一落点在 apply_action）。
        "transport-count-in" => {
            let _ = ui.invoke_key_action("d".into(), false, true, true, false);
        }
        "master-reset-fader" => ui.invoke_mixer_master_fader_reset(),
        "master-toggle-mono" => {
            ui.set_control_room_mono(!ui.get_control_room_mono());
            ui.invoke_control_room_toggle_mono();
        }
        "toggle-control-room" => {
            ui.set_show_control_room(!ui.get_show_control_room());
            ui.invoke_zone_toggle("control-room".into());
        }
        "toggle-inspector" => {
            ui.set_show_left_inspector(!ui.get_show_left_inspector());
            ui.invoke_zone_toggle("inspector".into());
        }
        // 与 `Action::ToggleBrowser` 同一语义（菜单条目走这里，快捷键走解析表）：
        // 左栏若关着就先展开，再把页签落到浏览器 —— 不做"切了页签却看不见"的半截动作。
        "toggle-browser" => {
            if !ui.get_show_left_inspector() {
                ui.set_show_left_inspector(true);
                ui.invoke_zone_toggle("inspector".into());
            }
            ui.set_left_panel_tab("browser".into());
        }
        // 网格强度（Logic Pro 13 的第 3 条借鉴）：默认 0=轻，可调到 1=标准 / 2=强。
        // 值一路传到 `Tokens.grid-strength`，四个派生网格色随之重新混合；
        // 不做持久化（视图态，不进工程、不进撤销栈，与 Logic 一致）。
        "grid-strength-light" | "grid-strength-normal" | "grid-strength-strong" => {
            let level = match cmd {
                "grid-strength-normal" => 1,
                "grid-strength-strong" => 2,
                _ => 0,
            };
            ui.global::<crate::ui::Tokens<'_>>()
                .set_grid_strength(level);
        }
        "toggle-clip-matrix" => {
            ui.set_show_clip_matrix(!ui.get_show_clip_matrix());
            ui.invoke_zone_toggle("clip-matrix".into());
        }
        "toggle-maximize-dock" => ui.invoke_console_maximize_toggle(),
        "toggle-automation" => {
            let next = !ui.get_automation_visible();
            ui.set_automation_visible(next);
            update_toast(
                ui,
                if next {
                    "[视图] 已展开自动化泳道"
                } else {
                    "[视图] 已收起自动化泳道"
                },
            );
        }
        "tab-pianoroll" => {
            ui.set_show_lower_dock(true);
            ui.invoke_apply_dock_tab("pianoroll".into());
        }
        "tab-mixer" => {
            ui.set_show_lower_dock(true);
            ui.invoke_apply_dock_tab("mixer".into());
        }
        "tab-devices" => {
            ui.set_show_lower_dock(true);
            ui.invoke_apply_dock_tab("devices".into());
        }
        "tab-stacked" => {
            ui.set_show_lower_dock(true);
            ui.invoke_apply_dock_tab("stacked".into());
        }
        "run-acoustic-diagnosis" => ui.invoke_run_acoustic_diagnosis(),
        "export-diagnostics" => ui.invoke_export_diagnostics(),
        "toggle-tooltips" => {
            let theme = ui.global::<crate::ui::Theme<'_>>();
            let next = !theme.get_show_tooltips();
            theme.set_show_tooltips(next);
            update_toast(
                ui,
                if next {
                    "[提示] 已开启悬浮功能提示"
                } else {
                    "[提示] 已关闭悬浮功能提示"
                },
            );
        }
        "toggle-hotspots" => {
            let next = !ui.get_show_hotspots();
            ui.set_show_hotspots(next);
            update_toast(
                ui,
                if next {
                    "[视图] 已开启架构热区透视"
                } else {
                    "[视图] 已关闭架构热区透视"
                },
            );
        }
        _ => {
            if cmd.contains("保存") || cmd.contains("save") {
                ui.invoke_save_project();
            } else if cmd.contains("打开") || cmd.contains("open") {
                ui.invoke_open_project();
            } else if cmd.contains("新建") || cmd.contains("new") {
                ui.invoke_new_project();
            } else if cmd.contains("撤销") || cmd.contains("undo") {
                ui.invoke_undo_step();
            } else if cmd.contains("重做") || cmd.contains("redo") {
                ui.invoke_redo_step();
            } else if cmd.contains("导出") && cmd.contains("WAV") {
                ui.invoke_open_export_wav();
            } else if cmd.contains("导出") && cmd.contains("MIDI") {
                ui.invoke_export_midi();
            } else if cmd.contains("导入") && cmd.contains("音频") {
                ui.invoke_import_audio();
            } else if cmd.contains("导入") && cmd.contains("MIDI") {
                ui.invoke_import_midi();
            } else if cmd.contains("SFZ") || cmd.contains("音色") {
                ui.invoke_load_sfz();
            } else if cmd.contains("录音") || cmd.contains("record") {
                ui.invoke_record_wav();
            } else if cmd.contains("播放") || cmd.contains("play") {
                ui.invoke_toggle_play();
            } else {
                update_toast(ui, format!("[命令] {cmd}"));
            }
        }
    }
}

/// 从新 UI 的卷帘音符 id(1-based, 与 `view_to_notes` 的 `id` 同源)解析工程里的音符身份。
///
/// 返回 `(track_id, clip_id, note_id, previous_note)`, 供 Delete/Modify/Split 这类
/// "自带撤销载荷"的 Op 使用; 先读活窗口/当前工程重投影(N1), ⛔ 不信过期装配快照。
fn aether_note_ref(
    ui: &MainWindow,
    fallback_view: &ViewState,
    project: &yeban_model::YebanProjectV1,
    ui_id: i32,
) -> Option<(
    yeban_model::EntityId,
    yeban_model::EntityId,
    yeban_model::EntityId,
    yeban_model::MidiNote,
)> {
    let index = usize::try_from(ui_id).ok()?.checked_sub(1)?;
    let selected_clip = ui.get_selected_clip_ulid();
    let note_id = if selected_clip.as_str().is_empty() {
        if let Some(ulid) = ui
            .get_note_ulids()
            .row_data(index)
            .and_then(|s| s.as_str().parse::<yeban_model::EntityId>().ok())
        {
            ulid
        } else if let Ok(live_view) = project_with_view_state(project, ui)
            && let Some(nv) = live_view.notes.get(index)
        {
            nv.id.parse::<yeban_model::EntityId>().ok()?
        } else {
            fallback_view
                .notes
                .get(index)?
                .id
                .parse::<yeban_model::EntityId>()
                .ok()?
        }
    } else if let Ok(live_view) = project_with_view_state(project, ui)
        && let Some(nv) = live_view.notes.get(index)
    {
        nv.id.parse::<yeban_model::EntityId>().ok()?
    } else if let Some(ulid) = ui
        .get_note_ulids()
        .row_data(index)
        .and_then(|s| s.as_str().parse::<yeban_model::EntityId>().ok())
    {
        ulid
    } else {
        fallback_view
            .notes
            .get(index)?
            .id
            .parse::<yeban_model::EntityId>()
            .ok()?
    };
    let (clip_id, track_id, _) = note_identity_for(project, note_id)?;
    let entry = project.clip_pool.get(&clip_id)?;
    let yeban_model::project::ClipContent::Midi { notes } = &entry.content else {
        return None;
    };
    let previous_note = notes.get(&note_id)?.clone();
    Some((track_id, clip_id, note_id, previous_note))
}

/// 提交一批真实 Op 并重投影(与 `wire_mixer_edit` 的松手提交同一条模型路径)。
fn aether_commit(ui: &MainWindow, port: &UndoPort, ops: Vec<yeban_model::Op>, label: &str) -> bool {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |elapsed| elapsed.as_millis() as u64);
    if port.commit_ops(now, label, ops).is_err() {
        return false;
    }
    refresh_undo_window(ui, port, true);
    true
}

fn device_name_matches(dev_name: &str, needle_lower: &str) -> bool {
    if needle_lower.is_empty() {
        return false;
    }
    let lower = dev_name.to_ascii_lowercase();
    lower == needle_lower || lower.contains(needle_lower)
}

fn param_name_is_alias(param_name: &str, needle_lower: &str) -> bool {
    matches!(
        (param_name.to_ascii_lowercase().as_str(), needle_lower),
        ("cutoff_hz", "cutoff") | ("cutoff", "cutoff_hz")
    )
}

fn find_device_param_exact(
    track: &yeban_model::project::TrackV3,
    dev_lower: &str,
    param_lower: &str,
    allow_alias: bool,
) -> Option<(usize, usize, f32)> {
    if dev_lower.is_empty() || param_lower.is_empty() {
        return None;
    }
    track.devices.iter().enumerate().find_map(|(slot, dev)| {
        device_name_matches(&dev.name, dev_lower)
            .then(|| {
                dev.params.iter().enumerate().find_map(|(pidx, p)| {
                    let matched = if allow_alias {
                        param_name_is_alias(&p.name, param_lower)
                    } else {
                        p.name.eq_ignore_ascii_case(param_lower)
                    };
                    matched.then_some((slot, pidx, p.value))
                })
            })
            .flatten()
    })
}

fn find_device_param_by_name(
    track: &yeban_model::project::TrackV3,
    param_lower: &str,
    allow_alias: bool,
) -> Option<(usize, usize, f32)> {
    if param_lower.is_empty() {
        return None;
    }
    track.devices.iter().enumerate().find_map(|(slot, dev)| {
        dev.params.iter().enumerate().find_map(|(pidx, p)| {
            let matched = if allow_alias {
                param_name_is_alias(&p.name, param_lower)
            } else {
                p.name.eq_ignore_ascii_case(param_lower)
            };
            matched.then_some((slot, pidx, p.value))
        })
    })
}

fn find_device_param_fallback(
    track: &yeban_model::project::TrackV3,
    dev_lower: &str,
) -> Option<(usize, usize, f32)> {
    if !dev_lower.is_empty()
        && let Some(found) = track.devices.iter().enumerate().find_map(|(slot, dev)| {
            device_name_matches(&dev.name, dev_lower)
                .then(|| dev.params.first().map(|p| (slot, 0, p.value)))
                .flatten()
        })
    {
        return Some(found);
    }
    track
        .devices
        .iter()
        .enumerate()
        .find_map(|(slot, dev)| dev.params.first().map(|p| (slot, 0, p.value)))
}

fn find_param_in_tracks<'a, I>(
    tracks: I,
    dev_lower: &str,
    param_lower: &str,
) -> Option<(yeban_model::EntityId, usize, usize, f32)>
where
    I: Iterator<Item = &'a yeban_model::project::TrackV3> + Clone,
{
    for allow_alias in [false, true] {
        for track in tracks.clone() {
            if let Some((s, p, v)) =
                find_device_param_exact(track, dev_lower, param_lower, allow_alias)
            {
                return Some((track.id, s, p, v));
            }
        }
    }
    for allow_alias in [false, true] {
        for track in tracks.clone() {
            if let Some((s, p, v)) = find_device_param_by_name(track, param_lower, allow_alias) {
                return Some((track.id, s, p, v));
            }
        }
    }
    for track in tracks {
        if let Some((s, p, v)) = find_device_param_fallback(track, dev_lower) {
            return Some((track.id, s, p, v));
        }
    }
    None
}

/// 按严格优先级解析 UI `device-param-changed` 回调的模型目标：
/// 1) 精确 `(设备名+参数名)`（先选中轨/机架轨，再全工程）
/// 2) 精确 `(参数名)`（先选中轨/机架轨，再全工程）
/// 3) 兼容别名 `(cutoff <-> cutoff_hz)`（设备+别名，再别名；同样先选中轨再全工程）
/// 4) 同设备/首设备首参数回退。
fn resolve_device_param_target(
    project: &yeban_model::YebanProjectV1,
    preferred_track_id: Option<&str>,
    device: &str,
    param: &str,
) -> Option<(yeban_model::EntityId, usize, usize, f32)> {
    let dev_lower = device.trim().to_ascii_lowercase();
    let param_lower = param.trim().to_ascii_lowercase();
    let explicit_track = preferred_track_id
        .and_then(|s| s.parse::<yeban_model::EntityId>().ok())
        .and_then(|id| project.tracks.get(&id));
    let rack_track = crate::bridge::display_track(project, preferred_track_id)
        .filter(|rack| explicit_track.is_none_or(|exp| exp.id != rack.id));
    let (pref_storage, pref_len) = match (explicit_track, rack_track) {
        (Some(a), Some(b)) => ([a, b], 2),
        (Some(a), None) | (None, Some(a)) => ([a, a], 1),
        (None, None) => {
            return find_param_in_tracks(project.tracks.values(), &dev_lower, &param_lower);
        }
    };
    let pref = &pref_storage[..pref_len];

    for allow_alias in [false, true] {
        if let Some(hit) = pref
            .iter()
            .copied()
            .find_map(|t| {
                find_device_param_exact(t, &dev_lower, &param_lower, allow_alias)
                    .map(|(s, p, v)| (t.id, s, p, v))
            })
            .or_else(|| {
                project.tracks.values().find_map(|t| {
                    find_device_param_exact(t, &dev_lower, &param_lower, allow_alias)
                        .map(|(s, p, v)| (t.id, s, p, v))
                })
            })
        {
            return Some(hit);
        }
        if let Some(hit) = pref
            .iter()
            .copied()
            .find_map(|t| {
                find_device_param_by_name(t, &param_lower, allow_alias)
                    .map(|(s, p, v)| (t.id, s, p, v))
            })
            .or_else(|| {
                project.tracks.values().find_map(|t| {
                    find_device_param_by_name(t, &param_lower, allow_alias)
                        .map(|(s, p, v)| (t.id, s, p, v))
                })
            })
        {
            return Some(hit);
        }
    }

    pref.iter()
        .copied()
        .find_map(|t| find_device_param_fallback(t, &dev_lower).map(|(s, p, v)| (t.id, s, p, v)))
        .or_else(|| {
            project.tracks.values().find_map(|t| {
                find_device_param_fallback(t, &dev_lower).map(|(s, p, v)| (t.id, s, p, v))
            })
        })
}

/// 新 UI 的 `FocusScope`（`key-handler` / 各模态陷阱）把逻辑键交给 `trigger-shortcut`；
/// 这里把它原样转给 `key-action`（`wire_keys` 的 `on_key_action`：`resolve_logical` +
/// `apply_action`）。修饰位取 Slint `KeyboardModifiers`（`alt`/`control`/`shift`/`meta`），
/// `control` 对应 `key-action` 的 `ctrl` 参数。
///
/// 生产（`main.rs` 的 `wire_aether_actions`）与无头判据（`live_surface.rs` 的
/// `build_live_ui_with`）调的是**同一个**函数：判据的平台按键（`dispatch_key_press`）
/// 与用户真键盘走同一条链；⛔ 不在判据侧再抄一份转发器。测试装配仍不跑
/// `wire_aether_actions` 的其余部分（走带按钮 / 轨道动作等生产桥接）。
pub fn wire_trigger_shortcut(ui: &MainWindow) {
    let weak = ui.as_weak();
    ui.on_trigger_shortcut({
        let w = weak.clone();
        move |text, event| {
            if let Some(ui) = w.upgrade() {
                ui.invoke_key_action(
                    text,
                    event.modifiers.shift,
                    event.modifiers.control,
                    event.modifiers.alt,
                    event.modifiers.meta,
                );
            }
        }
    });
}

/// ⭐ T-FIX-521：主控电平条点击 ⇒ 清过载锁存（`app.slint` 的 `meter-over-clear`）。
///
/// 无捕获闭包，只置一个线程局部请求位；真正的清空发生在下一跳 [`pump_meters`]
/// （那时才有 `&mut MeterRuntime`）。启动装配与换工程 `after` 重跑本函数都不会漏。
pub fn wire_meter_over_clear(ui: &MainWindow) {
    ui.on_meter_over_clear(|| {
        METER_OVER_CLEAR_REQUESTED.with(|flag| flag.set(true));
    });
}

/// 换工程后可重跑的“编辑面”接线（T-FIX-323）。
///
/// 这些回调的闭包都捕获 `UndoPort`，且注册在启动装配期；换工程只跑
/// [`crate::host::wire_view_callbacks`] 等旧回调不会重绑它们，`on_*` 覆盖语义下
/// 最后一次注册仍是启动期端口 ⇒ 编辑会落到旧撤销会话。启动装配与换工程 `after`
/// 必须调**同一个**本函数，避免两份清单分叉。
///
/// 只收**纯编辑面**：卷帘 / 片段拖动 / 轨道头 / 选中 / 缩放 / 移轨 / 滚动 /
/// 重命名 / ARM / 自动化车道 / 混音台 / 设备机架 / 发送条 / 宏 / BPM / 轨路由 /
/// 建片段。模块入口、对话框、文件选择器与音频设置另有工程目录 / 引擎 / 生产循环
/// 依赖，不在本函数内（它们仍按启动期装配，见 `main.rs` 的注释）。
pub fn wire_edit_surfaces(ui: &MainWindow, port: &Rc<UndoPort>) {
    wire_roll_edit(ui, port);
    wire_clip_drag(ui, port);
    wire_track_height_drag(ui, port);
    wire_track_select(ui, port);
    wire_zoom_controls(ui, port);
    wire_track_reorder(ui, port);
    wire_arrangement_wheel(ui, port);
    wire_arrangement_hscroll(ui, port);
    wire_track_rename(ui, port);
    wire_track_arm(ui);
    wire_automation_lane_click(ui, port);
    wire_mixer_edit(ui, port);
    wire_device_rack(ui, port);
    wire_send_strip(ui, port);
    wire_macro_panel(ui, port);
    wire_bpm_commit(ui, port);
    wire_track_strip(ui, port);
    wire_clip_create(ui, port);
    wire_meter_over_clear(ui);
}

/// 生产桥接层: 把**全部 33 个新 UI 独有回调**注册到真实 handler。
///
/// 落点分三类, ⛔ 没有一个是 toast / 静默:
/// * `fwd`  转发到 main.rs 已接线的旧回调(真实引擎 / 域逻辑);
/// * `Op`   经 [`UndoPort::commit_ops`] 提交真实领域操作并 [`refresh_undo_window`] 重投影;
/// * `view` 写 `MainWindow` 的真实视图态属性(被新组件树绑定消费) 或真实引擎读数。
///
/// ## 33 个回调的机械清单(逐个可在 `tests/aether_callback_matrix.rs` 活窗口验证)
///
/// | # | 回调 | 类别 | 真实落点 |
/// |---|---|---|---|
/// | 1 | `transport-toggle-play` | fwd | `invoke_toggle_play` -> EngineHost::toggle_play |
/// | 2 | `transport-toggle-rec` | fwd | `invoke_toggle_record` |
/// | 3 | `transport-toggle-loop` | fwd | `invoke_key_action("c")` -> ToggleCycle |
/// | 4 | `transport-rewind` | fwd | `invoke_stop` -> stop_and_rewind |
/// | 5 | `transport-set-bpm` | fwd | `invoke_bpm_commit` -> Op::SetTempo |
/// | 6 | `transport-set-scale` | Op+view | `Op::SetKeySignature` + `scale-text` |
/// | 7 | `trigger-shortcut` | fwd | `invoke_key_action`(含修饰位) |
/// | 8 | `track-selected` | fwd+view | `invoke_track_select` + `selected-track-index` |
/// | 9 | `track-toggle-mute` | fwd | `invoke_mixer_mute_toggle` -> Op::SetTrackMute |
/// | 10 | `track-toggle-solo` | fwd | `invoke_mixer_solo_toggle` -> Op::SetTrackSolo |
/// | 11 | `track-toggle-arm` | fwd | `invoke_track_arm_toggle` |
/// | 12 | `track-volume-changed` | Op | `Op::SetParam(TrackVolume)` |
/// | 13 | `track-add-requested` | fwd | `invoke_track_create_midi` -> Op::AddTrack |
/// | 14 | `edit-tool-selected` | fwd | `invoke_tool_selected` |
/// | 15 | `command-execute` | fwd | 分派到保存/打开/导出/撤销等旧回调 |
/// | 16 | `piano-note-create` | Op | `Op::AddNote` |
/// | 17 | `piano-note-delete` | Op | `Op::DeleteNote`(自带 previous_note) |
/// | 18 | `piano-note-velocity` | Op | `Op::ModifyNoteVelocity` |
/// | 19 | `piano-note-split` | Op | `Op::SetNoteTiming` + `Op::AddNote` |
/// | 20 | `piano-note-select` | view | `note-selected` + `selected-note-count` |
/// | 21 | `piano-step-toggle` | Op | 有则 `Op::DeleteNote`, 无则 `Op::AddNote` |
/// | 22 | `device-param-changed` | Op | `Op::SetParam(DeviceParam)` |
/// | 23 | `scene-trigger` | fwd | `invoke_scene_launch` -> Op::SetScene + 引擎 tempo |
/// | 24 | `clip-trigger` | fwd | 活投影解析 placement ULID -> `invoke_clip_select` |
/// | 25 | `chord-audition` | engine | `EngineHost::send_engine_events`(3 音 NoteOn/Off) + module-status 回执 |
/// | 26 | `piano-key-audition` | engine | `send_engine_events`(单音) + 回执 |
/// | 27 | `browser-item-load` | fwd+view | `sidebar-search` + `invoke_sidebar_search_changed` |
/// | 28 | `dock-tab-selected` | view | `console-tab`(F7/F8/F9 同一读数) |
/// | 29 | `zone-toggle` | view | `status-selection`(汇总四个 show-* 开关) |
/// | 30 | `monitor-switch` | engine+view | `EngineHost::device_name()` -> `status-selection` |
/// | 31 | `hot-swap-buffer-size` | view | `buffer-samples` + `dsp-cpu-percent` |
/// | 32 | `normalize-track-heights` | view+Op | `track-height-percent` + 清覆盖 + `apply_view` |
/// | 33 | `open-cmd-palette` | view | `show-cmd-palette` |
///
/// `engine` 与 `view` 由生产装配(`main.rs`)与活窗口判据传同一个句柄; 试听/监听
/// 走真实引擎事件与设备读数, 编辑一律走 [`UndoPort`] 而不是直接改 UI 数组。
///
/// 换工程后必须再调一次本函数接管的这一层：`main.rs` 的 `after` 闭包会重跑
/// [`crate::host::wire_view_callbacks`] 等旧回调，而 Slint 的 `on_*` 是覆盖语义。
/// 旧回调里同名的那批（轨道 MUTE/SOLO/ARM、控制室 DIM/MONO/SIDE、走带等）是
/// UI-only 版本，只重跑旧回调会把启动时这里接好的真实 handler 静默擦掉。
pub fn rewire_aether_actions_after_project_switch(
    ui: &MainWindow,
    port: Rc<UndoPort>,
    engine: Rc<RefCell<EngineHost>>,
    view: Rc<RefCell<ViewState>>,
) {
    // 混音台写入面（MUTE/SOLO/推子）闭包着 `UndoPort`，也必须换成换工程后的新端口；
    // 否则 aether 层的 `on_track_toggle_mute` 会转发给旧端口上的 `on_mixer_mute_toggle`。
    wire_mixer_edit(ui, &port);
    wire_aether_actions(ui, port, engine, view);
}

/// 生产窗口最后一道回调层：用 `on_*` 覆盖语义把新 UI 独有回调接到真实
/// handler / 引擎 / Op。启动装配与换工程后的重装都必须以本函数收尾。
pub fn wire_aether_actions(
    ui: &MainWindow,
    port: Rc<UndoPort>,
    engine: Rc<RefCell<EngineHost>>,
    view: Rc<RefCell<ViewState>>,
) {
    let weak = ui.as_weak();

    // ---- 走带 ----
    ui.on_transport_toggle_play({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                ui.invoke_toggle_play();
            }
        }
    });
    ui.on_transport_toggle_rec({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                ui.invoke_toggle_record();
            }
        }
    });
    ui.on_transport_rewind({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                ui.invoke_stop();
            }
        }
    });
    ui.on_transport_set_bpm({
        let w = weak.clone();
        move |bpm: i32| {
            if let Some(ui) = w.upgrade() {
                ui.invoke_bpm_commit(format!("{bpm}.00").into());
            }
        }
    });
    // `c` = Action::ToggleCycle(input.rs:1502), 与键盘同一条链。
    ui.on_transport_toggle_loop({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                ui.invoke_key_action("c".into(), false, false, false, false);
            }
        }
    });
    // 平台按键的转发（`trigger-shortcut` → `key-action`）：见 `wire_trigger_shortcut`。
    wire_trigger_shortcut(ui);

    // ---- 轨道 / 混音 (新 UI 传 1-based TrackData.id, 旧回调要 0-based 索引) ----
    ui.on_track_toggle_mute({
        let w = weak.clone();
        move |id: i32| {
            if let Some(ui) = w.upgrade() {
                ui.invoke_mixer_mute_toggle(id - 1);
            }
        }
    });
    ui.on_track_toggle_solo({
        let w = weak.clone();
        move |id: i32| {
            if let Some(ui) = w.upgrade() {
                ui.invoke_mixer_solo_toggle(id - 1);
            }
        }
    });
    ui.on_track_toggle_arm({
        let w = weak.clone();
        move |id: i32| {
            if let Some(ui) = w.upgrade() {
                ui.invoke_track_arm_toggle(id - 1);
            }
        }
    });
    ui.on_track_add_requested({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                ui.invoke_track_create_midi();
            }
        }
    });
    ui.on_track_selected({
        let w = weak.clone();
        move |id: i32| {
            if let Some(ui) = w.upgrade() {
                ui.set_selected_track_index(id);
                ui.invoke_track_select(id - 1);
            }
        }
    });
    // 推子: 没有同义旧回调, 直接提交 Op::SetParam(TrackVolume), 与 wire_mixer_edit
    // 的松手提交同一条模型路径(ADR-0005: 一次手势 = 一步可撤销编辑)。
    ui.on_track_volume_changed({
        let w = weak.clone();
        let port = Rc::clone(&port);
        move |id: i32, db: f32| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let Some(track_id) = track_id_at(&ui, id - 1) else {
                return;
            };
            let Ok(tid) = track_id.parse::<yeban_model::EntityId>() else {
                return;
            };
            let old_val = mixer_track_state(&port, &track_id).map_or(0.0, |state| state.volume_db);
            let op = yeban_model::Op::SetParam {
                target: yeban_model::AutomationTarget::TrackVolume { track_id: tid },
                old_val,
                new_val: db,
            };
            let now = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map_or(0, |elapsed| elapsed.as_millis() as u64);
            if port.commit_ops(now, "aether: 推子", vec![op]).is_err() {
                ui.set_toast_message("推子提交被拒绝(工程未改)".into());
            } else {
                refresh_undo_window(&ui, &port, true);
            }
        }
    });

    ui.on_track_pan_changed({
        let w = weak.clone();
        let port = Rc::clone(&port);
        move |id: i32, pan: f32| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let clamped = pan.clamp(-1.0, 1.0);
            let Some(track_id) = track_id_at(&ui, id - 1) else {
                return;
            };
            let Ok(tid) = track_id.parse::<yeban_model::EntityId>() else {
                return;
            };
            preview_track_pan(&ui, id - 1, clamped);
            let old_val = mixer_track_state(&port, &track_id).map_or(0.0, |state| state.pan);
            if (old_val - clamped).abs() <= f32::EPSILON {
                return;
            }
            let op = yeban_model::Op::SetParam {
                target: yeban_model::AutomationTarget::TrackPan { track_id: tid },
                old_val,
                new_val: clamped,
            };
            if aether_commit(&ui, &port, vec![op], "aether: 声像") {
                let pan_text = crate::bridge::pan_display(pan_millis_of(clamped));
                ui.set_status_selection(format!("轨道 #{} 声像: {}", id, pan_text).into());
            } else {
                update_toast(&ui, "声像提交被拒绝(工程未改)");
            }
        }
    });

    ui.on_track_instrument_change({
        let w = weak.clone();
        let port = Rc::clone(&port);
        move |id: i32, inst: SharedString| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let inst_str = inst.as_str();
            match inst_str {
                "fx:eq" => {
                    select_aether_track_for_action(&ui, id);
                    ui.invoke_device_insert_eq();
                    return;
                }
                "fx:reverb" => {
                    select_aether_track_for_action(&ui, id);
                    ui.invoke_device_insert_reverb();
                    return;
                }
                "fx:compressor" | "fx:comp" => {
                    select_aether_track_for_action(&ui, id);
                    insert_builtin_device(
                        &ui,
                        &port,
                        crate::bridge::BuiltinEffect::Compressor,
                        DeviceTarget::DisplayTrack,
                    );
                    return;
                }
                "sfz:default" => {
                    select_aether_track_for_action(&ui, id);
                    ui.invoke_load_sfz();
                    return;
                }
                _ => {}
            }
            let Some(project) = port.try_project() else {
                return;
            };
            let tid = if id > 0 {
                track_id_at(&ui, id - 1)
                    .and_then(|s| s.parse::<yeban_model::EntityId>().ok())
                    .or_else(|| display_track(&ui, &project).map(|t| t.id))
            } else {
                display_track(&ui, &project).map(|t| t.id)
            };
            let Some(tid) = tid.or_else(|| project.tracks.keys().next().copied()) else {
                return;
            };
            let Some(track) = project.tracks.get(&tid) else {
                return;
            };
            if let Some(path) = inst_str.strip_prefix("sfz:") {
                let trimmed = path.trim();
                if trimmed.is_empty() {
                    let msg = "[音色] SFZ 路径为空，未加载";
                    ui.set_module_status(msg.into());
                    ui.set_module_status_succeeded(false);
                    update_toast(&ui, msg);
                    return;
                }
                match crate::bridge::probe_instrument_samples(trimmed) {
                    crate::bridge::InstrumentSampleProbe::Installable { decoded_samples } => {
                        let stored = crate::samples::normalize_sampler_path_for_storage(trimmed);
                        let op = yeban_model::Op::SetTrackSampler {
                            track_id: tid,
                            old_sampler: track.sampler.clone(),
                            new_sampler: Some(yeban_model::SamplerBinding { note_octave_override: None, path: stored }),
                        };
                        if aether_commit(&ui, &port, vec![op], "aether: 更换 SFZ 音色") {
                            let msg = format!(
                                "[音色] 已加载 SFZ: {} ({decoded_samples} 样本)",
                                instrument_display_label(inst_str)
                            );
                            ui.set_module_status(msg.clone().into());
                            ui.set_module_status_succeeded(true);
                            update_toast(&ui, msg);
                        }
                    }
                    crate::bridge::InstrumentSampleProbe::MissingSamples {
                        missing_files,
                        silent_regions,
                        ..
                    } => {
                        let msg = format!(
                            "[音色] 拒绝加载 SFZ: 缺 {missing_files} 个样本 / {silent_regions} 个静音区域 ({trimmed})"
                        );
                        ui.set_module_status(msg.clone().into());
                        ui.set_module_status_succeeded(false);
                        update_toast(&ui, msg);
                    }
                    crate::bridge::InstrumentSampleProbe::UnreadableSfz => {
                        let msg = format!("[音色] SFZ 文件不存在或解析失败: {trimmed}");
                        ui.set_module_status(msg.clone().into());
                        ui.set_module_status_succeeded(false);
                        update_toast(&ui, msg);
                    }
                }
                return;
            }
            let Some((name, param_specs)) = synth_preset_definition(inst_str) else {
                update_toast(&ui, format!("[音色] 未识别的预设: {inst_str}"));
                return;
            };
            let mut ops = Vec::new();
            for (slot_index, dev) in track.devices.iter().enumerate().rev() {
                if dev.kind == yeban_model::project::DeviceKind::InternalInstrument {
                    ops.push(yeban_model::Op::RemoveDevice {
                        track_id: tid,
                        slot_index,
                        previous_device: dev.clone(),
                    });
                }
            }
            if let Some(old_sampler) = &track.sampler {
                ops.push(yeban_model::Op::SetTrackSampler {
                    track_id: tid,
                    old_sampler: Some(old_sampler.clone()),
                    new_sampler: None,
                });
            }
            let device = yeban_model::project::DeviceDefinition {
                id: yeban_model::EntityId::new(),
                name: name.clone(),
                kind: yeban_model::project::DeviceKind::InternalInstrument,
                bypassed: false,
                params: param_specs
                    .into_iter()
                    .map(
                        |(pname, value, unit)| yeban_model::project::ParameterValue {
                            name: pname.to_owned(),
                            value,
                            unit: unit.map(str::to_owned),
                        },
                    )
                    .collect(),
                latency_samples: 0,
                plugin: None,
            };
            ops.push(yeban_model::Op::InsertDevice {
                track_id: tid,
                slot_index: 0,
                device,
            });
            if aether_commit(&ui, &port, ops, &format!("aether: 音色 {name}")) {
                update_toast(&ui, format!("[音色] 轨道“{}”已切换为 {name}", track.name));
            } else {
                update_toast(&ui, format!("[音色] 切换 {name} 被拒绝(工程未改)"));
            }
        }
    });

    // ⭐ T-FIX-190：控制室三开关**真正接进引擎监听输出级**（生产路径）。
    //
    // `.slint` 先翻 `is-dim/is-mono/is-side`（与 MainWindow 的 `control-room-*`
    // 属性双向绑定），再调本回调 ⇒ 这里读到的就是**翻转后的新值**，直接写进引擎
    // 的监听开关（原子；设备腿上也生效）。`update_control_room_status` 只留状态
    // 字符串＋toast（显示面不变）。下坞 `master-toggle-mono` 翻属性后调
    // `invoke_control_room_toggle_mono` ⇒ 走同一条回调，MONO 臂一并覆盖。
    ui.on_control_room_toggle_dim({
        let w = weak.clone();
        let engine = Rc::clone(&engine);
        move || {
            if let Some(ui) = w.upgrade() {
                engine.borrow().set_monitor_dim(ui.get_control_room_dim());
                update_control_room_status(&ui, "DIM");
            }
        }
    });
    ui.on_control_room_toggle_mono({
        let w = weak.clone();
        let engine = Rc::clone(&engine);
        move || {
            if let Some(ui) = w.upgrade() {
                engine.borrow().set_monitor_mono(ui.get_control_room_mono());
                update_control_room_status(&ui, "MONO");
            }
        }
    });
    ui.on_control_room_toggle_side({
        let w = weak.clone();
        let engine = Rc::clone(&engine);
        move || {
            if let Some(ui) = w.upgrade() {
                engine.borrow().set_monitor_side(ui.get_control_room_side());
                update_control_room_status(&ui, "SIDE");
            }
        }
    });

    // ---- 音符编辑: 新 UI 卷帘网格 -> 真实 Op::AddNote ----
    // 先按 selected-clip-ulid -> display_track 已放置 MIDI 片段寻址(N2/N3)，
    // 音高解除 16 行夹紧上限以支持低音区与全步长(N4)，写入后同时触发试听。
    ui.on_piano_note_create({
        let w = weak.clone();
        let port = Rc::clone(&port);
        move |row: i32, step: i32| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let Some(project) = port.try_project() else {
                return;
            };
            let pitch = (84 - row).clamp(0, 127) as u8;
            let start_tick = u64::try_from(step.max(0)).unwrap_or(0) * 240;
            let note =
                yeban_model::MidiNote::new(yeban_model::EntityId::new(), start_tick, pitch, 240);
            let selected_track = selected_track_id(&ui);
            let selected_clip = ui.get_selected_clip_ulid().to_string();
            let inserted = match build_roll_note_insert_ops(
                &project,
                selected_track.as_deref(),
                Some(selected_clip.as_str()),
                note,
            ) {
                Ok(inserted) => inserted,
                Err(reason) => {
                    ui.set_roll_edit_status(reason.into());
                    update_toast(&ui, reason);
                    return;
                }
            };
            if let Err(err) = port.commit_ops(now_ms(), "aether: 新建音符", inserted.ops.clone())
            {
                eprintln!("[yeban-app] aether commit rejected: {err}");
                ui.set_roll_edit_status("新建音符被拒绝(工程未改)".into());
                update_toast(&ui, "新建音符被拒绝(工程未改)");
            } else {
                if let Some(updated_project) = port.try_project() {
                    sync_roll_target_selection(&ui, &updated_project, &inserted);
                }
                if let Some(notice) = auto_insert_status_message(&inserted) {
                    ui.set_roll_edit_status(notice.into());
                    update_toast(&ui, notice);
                } else {
                    ui.set_roll_edit_status("".into());
                }
                refresh_undo_window(&ui, &port, true);
                ui.invoke_piano_key_audition(midi_pitch_name(pitch).into(), row);
            }
        }
    });

    // ---- 工具矩阵 (新 UI 用字符串工具名, 旧回调要数字档位) ----
    ui.on_edit_tool_selected({
        let w = weak.clone();
        move |tool| {
            if let Some(ui) = w.upgrade() {
                let digit = match tool.as_str() {
                    "pointer" => 1,
                    "draw" | "pencil" => 2,
                    "split" | "knife" => 3,
                    "range" | "velocity" => 4,
                    "erase" | "eraser" => 5,
                    _ => 1,
                };
                ui.invoke_tool_selected(digit);
            }
        }
    });

    // ---- 命令面板 / 顶部菜单栏: 把命令 ID 分派到已接线的真实回调 ----
    ui.on_command_execute({
        let w = weak.clone();
        let port = Rc::clone(&port);
        // ⭐ T-FIX-167：分轨臂读真实工程目录（见下）；`engine` 是生产那同一个
        // `Rc<RefCell<EngineHost>>`（`engine_handle`），打开/另存为时已写下
        // `project_dir`，点击时现读 ⇒ 换工程之后不陈旧。
        let engine = Rc::clone(&engine);
        move |cmd| {
            if let Some(ui) = w.upgrade() {
                let w = w.clone();
                match cmd.as_str() {
                    // 剪贴板三键的**菜单入口**（与键盘同一组函数，ADR-0076 B3）。
                    "edit-copy" => {
                        if let Some(project) = port.try_project() {
                            let ok = clipboard_copy_selected(&ui, &project);
                            report_clipboard(&ui, ClipboardVerb::Copy, ok);
                        }
                    }
                    "edit-paste" => {
                        if let Some(project) = port.try_project() {
                            let ok = clipboard_paste(&ui, &port, &project);
                            report_clipboard(&ui, ClipboardVerb::Paste, ok);
                        }
                    }
                    "edit-cut" => {
                        if let Some(project) = port.try_project() {
                            let ok = clipboard_cut(&ui, &port, &project);
                            report_clipboard(&ui, ClipboardVerb::Cut, ok);
                        }
                    }
                    "place-audio-clip" => place_latest_audio_clip(&ui, &port),
                    // ⭐ 分轨导出 GUI 入口（ADR-0076 B5）：后端与 CLI / MCP **同一份**
                    // （`crate::export_stems::export_stems`）；这里只补「定输出目录 + 线程 + 回执」。
                    // ⚠ 本回调（`wire_aether_actions`）没有 `ModulePaths` 捕获 ⇒ 目录按
                    // 「用户可预期且不会被系统清理」的固定位置推导（`stems_output_dir`），
                    // 不再落在 `%TEMP%`（Windows 磁盘清理会连整份分轨一起删掉）。
                    // （GUI 目录选择器属后续切片，见 ADR-0076 B5。）
                    "export-stems" => {
                        let out_dir = stems_output_dir();
                        if let Err(err) = std::fs::create_dir_all(&out_dir) {
                            ui.set_toast_message(
                                format!("[导出] 无法创建分轨目录 {}：{err}", out_dir.display())
                                    .into(),
                            );
                            return;
                        }
                        let Some(project) = port.try_project() else {
                            ui.set_toast_message("[导出] 没有活跃工程，无法导出分轨".into());
                            return;
                        };
                        // ⭐ T-FIX-422：分轨导出的 `project_path` 必须是**真实工程文件路径**
                        // （相对 SFZ 的解析根＋`guard_output_path` 的工程文件/锁文件基准）。
                        // T-FIX-167 的目录合成名 `project_dir/project.yeban` 只够解析，护栏
                        // 拿它比对等于在护一个不存在的文件；未保存工程也不能回退到输出目录
                        // 占位（那是 T-FIX-189 的原始根因之一）。这里点击时现读：
                        // - 从文件打开 / 另存为成功 ⇒ `EngineHost` 记着的真实路径；
                        // - 新建未保存 / 内置样本 ⇒ cwd（与 CLI `--export-stems` 样本工程
                        //   的 `project_path` 口径逐字相同），⛔ 不再拿 `out_dir` 占位。
                        let project_path = stems_project_path(&engine.borrow());
                        // ⭐ T-FIX-188：资产池与保存同一来源（`UndoPort::assets()`）——
                        //   装配点（`main.rs` 的 `--open` / `open_archive_runtime`）已把
                        //   归档的 `assets/{sha256}` 换进这只端口；空池会让内嵌样本
                        //   的轨静音（`render::resolve_asset`：索引有、池里无 ⇒ 登记 + 静音）。
                        //   与 CLI（`cli.rs` 的 `&loaded.archive.assets`）和 TUI
                        //   （`yeban-tui` 的 `archive.assets.clone()`）同口径。⛔ 不写死空池。
                        let assets = port.assets();
                        let worker = w.clone();
                        let out_for_msg = out_dir.clone();
                        let _ = std::thread::spawn(move || {
                            let result = crate::export_stems::export_stems(
                                &project,
                                &project_path,
                                &out_dir,
                                None,
                                &assets,
                            );
                            let _ = worker.upgrade_in_event_loop(move |ui| match result {
                                Ok(report) => ui.set_toast_message(
                                    // T-FIX-418：文案判定收进 `export_stems::toast_message`
                                    // —— 音频片段有未渲染时降级为"分轨警告"，零未渲染时
                                    // 仍是原来的"分轨完成"；这里只拼、不再判。
                                    crate::export_stems::toast_message(&report, &out_for_msg)
                                        .into(),
                                ),
                                Err(err) => {
                                    ui.set_toast_message(format!("[导出] 分轨失败：{err}").into())
                                }
                            });
                        });
                    }
                    // ⭐ 菜单「退出 Yeban」：先藏窗口再退事件循环。
                    // `main.rs` 走 `slint::ComponentHandle::run(&ui)` ⇒ `quit_event_loop()`
                    // 是唯一正确的出口；`hide()` 先做是为了把"点菜单到进程结束"之间
                    // 的空窗时间压到最短（视觉上不会留一个白框）。
                    "app-quit" => {
                        // ⭐ T-FIX-391：退出前若有录音，先走现有 stop→land 路径把
                        // take 落进当前工程；⛔ 不让未完成录音随进程消失。
                        if recording_in_progress() {
                            ui.invoke_record_wav();
                        }
                        // ⭐ T-FIX-208：有未保存改动先拦一下，弹三选框让用户选
                        // 「保存并退出 / 直接退出 / 取消」，⛔ 不再一键丢掉全部编辑。
                        // 判据走 crate::dirty_guard —— 与保存点同一个真源（head 指针）。
                        // 未安装保存点的判据装配里 current_is_dirty 恒 false ⇒ 逐位沿用旧行为。
                        if crate::dirty_guard::current_is_dirty(port.display().head) {
                            ui.set_quit_confirm_open(true);
                        } else {
                            // `hide()` 返回 `Result`：退出路径上藏不住窗口不算致命，
                            // 但也不能 `.unwrap()`（窗口已被系统收走时会 panic）。
                            let _ = ui.window().hide();
                            if let Err(err) = slint::quit_event_loop() {
                                ui.set_toast_message(
                                    format!("[退出] 事件循环未退出：{err}").into(),
                                );
                            }
                        }
                    }
                    // ⭐ 帮助菜单四入口（line/onboarding-help）：落点全在
                    // `crate::help`，数据面由那一层写进 MainWindow 属性。
                    "help-manual" => crate::help::open_manual(&ui),
                    "help-shortcuts" => crate::help::open_shortcuts(&ui),
                    "help-onboarding" => crate::help::open_onboarding(&ui),
                    "help-lessons" => crate::help::open_lessons(&ui, &port),
                    // ⭐ T-FIX-312：最近工程清单的清空入口（命令面板 / 菜单
                    // 走 on_command_execute 的同一个分派点）。单条移除的另一条
                    // 路由"打开文件失败 ⇒ forget_recent_project"在启动选择器臂里。
                    "recent-clear" => {
                        crate::settings::clear_recent_projects();
                        let notice = "最近工程清单已清空（settings.json 已写回）";
                        update_toast(&ui, notice);
                    }
                    // ⭐ T-FIX-487：按锚点打开帮助（`help-topic:<anchor>`），
                    // 落点是 `crate::help::open_help_topic`（注册表精确匹配，
                    // 表外锚点只报提示、不打开）。必须放在 `other` 臂之前。
                    other if other.starts_with("help-topic:") => {
                        let anchor = &other["help-topic:".len()..];
                        crate::help::open_help_topic(&ui, anchor, &port);
                    }
                    other => dispatch_aether_command(&ui, other),
                }
            }
        }
    });

    // 回滚按钮 -> 撤销一步(与 Cmd+Z 同一个 UndoPort)。
    ui.on_revert_to_last_commit({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                ui.invoke_undo_step();
            }
        }
    });

    // =====================================================================
    // 其余 18 个新 UI 独有回调 —— 全部落到真实属性 / 真实 Op / 真实引擎事件,
    // ⛔ 不是 toast。每个都可由 tests/aether_callback_matrix.rs 在活窗口逐个验证。
    // =====================================================================

    // ① transport-set-scale: 写 scale-text 显示态 + 提交 Op::SetKeySignature(改工程)。
    ui.on_transport_set_scale({
        let w = weak.clone();
        let port = Rc::clone(&port);
        move |text| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            ui.set_scale_text(text.clone());
            let new_key_signature = Some(parse_key_signature_text(text.as_str()));
            let Some(project) = port.try_project() else {
                return;
            };
            let old_key_signature = project.key_signature;
            if old_key_signature != new_key_signature {
                aether_commit(
                    &ui,
                    &port,
                    vec![yeban_model::Op::SetKeySignature {
                        old_key_signature,
                        new_key_signature,
                    }],
                    "aether: 调号",
                );
            }
        }
    });

    // ② device-param-changed: 优先按选中轨与设备/参数名精确解析，无果再按 4 层回退定位目标。
    ui.on_device_param_changed({
        let w = weak.clone();
        let port = Rc::clone(&port);
        move |device, param, value| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let Some(project) = port.try_project() else {
                return;
            };
            let preferred = ui.get_selected_track_id();
            let Some((track_id, slot_index, param_index, old_val)) = resolve_device_param_target(
                &project,
                (!preferred.is_empty()).then_some(preferred.as_str()),
                device.as_str(),
                param.as_str(),
            ) else {
                return;
            };
            let op = yeban_model::Op::SetParam {
                target: yeban_model::project::AutomationTarget::DeviceParam {
                    track_id,
                    slot_index,
                    param_index,
                },
                old_val,
                new_val: value,
            };
            aether_commit(&ui, &port, vec![op], "aether: 设备参数");
        }
    });

    // ③ piano-note-delete: UI 音符 id -> Op::DeleteNote(自带 previous_note 撤销载荷)。
    ui.on_piano_note_delete({
        let w = weak.clone();
        let port = Rc::clone(&port);
        let view = Rc::clone(&view);
        move |id| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let Some(project) = port.try_project() else {
                return;
            };
            let borrowed = view.borrow();
            let Some((track_id, clip_id, note_id, previous_note)) =
                aether_note_ref(&ui, &borrowed, &project, id)
            else {
                return;
            };
            drop(borrowed);
            aether_commit(
                &ui,
                &port,
                vec![yeban_model::Op::DeleteNote {
                    track_id,
                    clip_id,
                    note_id,
                    previous_note,
                }],
                "aether: 删除音符",
            );
        }
    });

    // ④ piano-note-velocity: Op::ModifyNoteVelocity(旧力度来自权威工程)。
    ui.on_piano_note_velocity({
        let w = weak.clone();
        let port = Rc::clone(&port);
        let view = Rc::clone(&view);
        move |id, velocity| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let Some(project) = port.try_project() else {
                return;
            };
            let borrowed = view.borrow();
            let Some((track_id, clip_id, note_id, note)) =
                aether_note_ref(&ui, &borrowed, &project, id)
            else {
                return;
            };
            drop(borrowed);
            let new_vel = velocity.clamp(0, 127) as u8;
            aether_commit(
                &ui,
                &port,
                vec![yeban_model::Op::ModifyNoteVelocity {
                    track_id,
                    clip_id,
                    note_id,
                    old_vel: note.velocity,
                    new_vel,
                }],
                "aether: 音符力度",
            );
        }
    });

    // ⑤ piano-note-split: 两步同一提交 —— 原音符时值减半 + 补一个后半音符。
    ui.on_piano_note_split({
        let w = weak.clone();
        let port = Rc::clone(&port);
        let view = Rc::clone(&view);
        move |id| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let Some(project) = port.try_project() else {
                return;
            };
            let borrowed = view.borrow();
            let Some((track_id, clip_id, _note_id, note)) =
                aether_note_ref(&ui, &borrowed, &project, id)
            else {
                return;
            };
            drop(borrowed);
            let half = (note.duration_ticks / 2).max(1);
            let mut second = note.clone();
            second.id = yeban_model::EntityId::new();
            second.start_tick = note.start_tick.saturating_add(half);
            second.duration_ticks = note.duration_ticks.saturating_sub(half).max(1);
            let ops = vec![
                yeban_model::Op::SetNoteTiming {
                    track_id,
                    clip_id,
                    note_id: note.id,
                    old_start_tick: note.start_tick,
                    old_duration_ticks: note.duration_ticks,
                    new_start_tick: note.start_tick,
                    new_duration_ticks: half,
                },
                yeban_model::Op::AddNote {
                    track_id,
                    clip_id,
                    note: second,
                },
            ];
            aether_commit(&ui, &port, ops, "aether: 拆分音符");
        }
    });

    // ⑥ piano-note-select: 写 note-selected 数组 + selected-note-count(卷帘真实消费)。
    ui.on_piano_note_select({
        let w = weak.clone();
        move |id| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let count = ui.get_notes().iter().count();
            let selected: Vec<bool> = (1..=count).map(|n| n as i32 == id).collect();
            let hits = selected.iter().filter(|v| **v).count();
            ui.set_note_selected(ModelRc::new(VecModel::from(selected)));
            ui.set_selected_note_count(hits as i32);
        }
    });

    // ⑦ piano-step-toggle: step sequencer 格子 -> 有则删、无则自动建轨/片段/乐器并插音符。
    ui.on_piano_step_toggle({
        let w = weak.clone();
        let port = Rc::clone(&port);
        move |row, step| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let Some(project) = port.try_project() else {
                return;
            };
            let start_tick = u64::try_from(step.max(0)).unwrap_or(0) * 240;
            let pitch = (84 - row).clamp(0, 127) as u8;
            let existing = if let Ok((track_id, fallback_clip_id)) =
                resolve_roll_target(&ui, &project)
            {
                let track = project.tracks.get(&track_id);
                let selected_clip = ui.get_selected_clip_ulid();
                let preferred = Some(selected_clip.trim())
                    .filter(|s| !s.is_empty())
                    .and_then(|sel| {
                        track.and_then(|t| {
                            t.clips.values().find(|p| {
                                (p.id.to_canonical_string() == sel
                                    || p.clip_id.to_canonical_string() == sel)
                                    && start_tick >= p.start_tick
                                    && start_tick < p.start_tick.saturating_add(p.duration_ticks)
                                    && matches!(
                                        project.clip_pool.get(&p.clip_id).map(|e| &e.content),
                                        Some(yeban_model::project::ClipContent::Midi { .. })
                                    )
                            })
                        })
                    });
                let covering = preferred.or_else(|| {
                    track.and_then(|t| {
                        t.clips.values().find(|p| {
                            start_tick >= p.start_tick
                                && start_tick < p.start_tick.saturating_add(p.duration_ticks)
                                && matches!(
                                    project.clip_pool.get(&p.clip_id).map(|e| &e.content),
                                    Some(yeban_model::project::ClipContent::Midi { .. })
                                )
                        })
                    })
                });
                let (target_clip_id, placement_start) = covering
                    .map(|p| (p.clip_id, p.start_tick))
                    .unwrap_or_else(|| {
                        let fallback_start = track
                            .and_then(|t| {
                                t.clips
                                    .values()
                                    .filter(|p| p.clip_id == fallback_clip_id)
                                    .map(|p| p.start_tick)
                                    .min()
                            })
                            .unwrap_or(0);
                        (fallback_clip_id, fallback_start)
                    });
                project
                    .clip_pool
                    .get(&target_clip_id)
                    .and_then(|entry| match &entry.content {
                        yeban_model::project::ClipContent::Midi { notes } => notes
                            .values()
                            .find(|n| {
                                placement_start.saturating_add(n.start_tick) == start_tick
                                    && n.pitch == pitch
                            })
                            .cloned()
                            .map(|note| (track_id, target_clip_id, note)),
                        _ => None,
                    })
            } else {
                None
            };
            if let Some((track_id, clip_id, note)) = existing {
                let op = yeban_model::Op::DeleteNote {
                    track_id,
                    clip_id,
                    note_id: note.id,
                    previous_note: note,
                };
                if aether_commit(&ui, &port, vec![op], "aether: 步进格") {
                    ui.set_roll_edit_status("".into());
                }
                return;
            }
            let note =
                yeban_model::MidiNote::new(yeban_model::EntityId::new(), start_tick, pitch, 240);
            let selected_track = selected_track_id(&ui);
            let selected_clip = ui.get_selected_clip_ulid().to_string();
            let inserted = match build_roll_note_insert_ops(
                &project,
                selected_track.as_deref(),
                Some(selected_clip.as_str()),
                note,
            ) {
                Ok(inserted) => inserted,
                Err(reason) => {
                    ui.set_roll_edit_status(reason.into());
                    update_toast(&ui, reason);
                    return;
                }
            };
            if port
                .commit_ops(now_ms(), "aether: 步进格", inserted.ops.clone())
                .is_ok()
            {
                if let Some(updated_project) = port.try_project() {
                    sync_roll_target_selection(&ui, &updated_project, &inserted);
                }
                if let Some(notice) = auto_insert_status_message(&inserted) {
                    ui.set_roll_edit_status(notice.into());
                    update_toast(&ui, notice);
                } else {
                    ui.set_roll_edit_status("".into());
                }
                refresh_undo_window(&ui, &port, true);
                ui.invoke_piano_key_audition(midi_pitch_name(pitch).into(), row);
            }
        }
    });

    // ⑧ scene-trigger: 转发到 wire_scene_launch 的真实入口(提交 Op::SetScene + 引擎 tempo)。
    ui.on_scene_trigger({
        let w = weak.clone();
        move |index| {
            if let Some(ui) = w.upgrade() {
                ui.invoke_scene_launch(index);
            }
        }
    });

    // ⑨ clip-trigger: 从活投影解析 clip ULID, 转发到 wire_clip_scope 的真实选中入口。
    ui.on_clip_trigger({
        let w = weak.clone();
        move |_track, clip_idx| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            // 与 `wire_clip_scope` 的准入检查同源: 直接用注入面的 clip-ulids,
            // ⛔ 不从投影另算一遍(两处口径会漂移)。
            let index = usize::try_from(clip_idx).unwrap_or(usize::MAX);
            let Some(ulid) = ui.get_clip_ulids().row_data(index) else {
                return;
            };
            ui.invoke_clip_select(ulid);
        }
    });

    // ⑩/⑪ chord / piano-key 试听: 真实 EngineEvent::NoteOn/Off 注入引擎, 回执写 module-status。
    ui.on_chord_audition({
        let w = weak.clone();
        let engine = Rc::clone(&engine);
        let port = Rc::clone(&port);
        move |chord| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let pitches = match parse_chord_pitches(chord.as_str()) {
                Ok(pitches) => pitches,
                Err(err) => {
                    ui.set_module_status(format!("试听: {err}").into());
                    ui.set_module_status_succeeded(false);
                    return;
                }
            };
            let Some((track, warning)) =
                resolve_and_prepare_audition_target(&ui, &port, &engine, &pitches)
            else {
                ui.set_module_status("试听: 工程里没有音轨".into());
                ui.set_module_status_succeeded(false);
                return;
            };
            dispatch_aether_audition(&ui, &engine, track, &pitches, 96, "试听和弦", warning);
        }
    });
    ui.on_piano_key_audition({
        let w = weak.clone();
        let engine = Rc::clone(&engine);
        let port = Rc::clone(&port);
        move |key, row| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let pitch =
                parse_pitch_name(key.as_str()).unwrap_or_else(|| (84 - row).clamp(0, 127) as u8);
            let Some((track, warning)) =
                resolve_and_prepare_audition_target(&ui, &port, &engine, &[pitch])
            else {
                ui.set_module_status("试听: 工程里没有音轨".into());
                ui.set_module_status_succeeded(false);
                return;
            };
            dispatch_aether_audition(&ui, &engine, track, &[pitch], 100, "试听琴键", warning);
        }
    });

    let active_pressed_keys: Rc<
        RefCell<std::collections::BTreeMap<i32, (yeban_model::EntityId, u8)>>,
    > = Rc::new(RefCell::new(std::collections::BTreeMap::new()));
    ui.on_piano_key_pressed({
        let w = weak.clone();
        let engine = Rc::clone(&engine);
        let port = Rc::clone(&port);
        let active_keys = Rc::clone(&active_pressed_keys);
        move |lane| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let Some(pitch) = crate::bridge::pitch_for_lane_with_base(lane, roll_base_pitch(&ui))
            else {
                return;
            };
            let Some((track, warning)) =
                resolve_and_prepare_audition_target(&ui, &port, &engine, &[pitch])
            else {
                ui.set_module_status("试听: 工程里没有音轨".into());
                ui.set_module_status_succeeded(false);
                return;
            };
            if !engine.borrow().has_engine() {
                ui.set_module_status("试听: 引擎未接线（工程可继续编辑）".into());
                ui.set_module_status_succeeded(false);
                return;
            }
            let stale = active_keys.borrow_mut().remove(&lane);
            let written = {
                let mut host = engine.borrow_mut();
                if let Some((old_track, old_pitch)) = stale {
                    let _ = host.send_engine_events(&[yeban_engine::ring::EngineEvent::NoteOff {
                        track: old_track,
                        pitch: old_pitch,
                    }]);
                }
                host.send_engine_events(&[yeban_engine::ring::EngineEvent::NoteOn {
                    track,
                    pitch,
                    velocity: 100,
                }])
            };
            active_keys.borrow_mut().insert(lane, (track, pitch));
            let pitch_label = midi_pitch_name(pitch);
            let msg = match warning {
                Some(warn) => {
                    ui.set_roll_edit_status(format!("试听提示: {warn}").into());
                    format!("试听琴键({pitch_label}): 引擎事件通道已调用, 写入 {written} 条（提示: {warn}）")
                }
                None => {
                    if ui.get_roll_edit_status().as_str().starts_with("试听提示:") {
                        ui.set_roll_edit_status("".into());
                    }
                    format!("试听琴键({pitch_label}): 引擎事件通道已调用, 写入 {written} 条")
                }
            };
            ui.set_module_status(msg.into());
            ui.set_module_status_succeeded(true);
        }
    });
    ui.on_piano_key_released({
        let w = weak.clone();
        let engine = Rc::clone(&engine);
        let port = Rc::clone(&port);
        let active_keys = Rc::clone(&active_pressed_keys);
        move |lane| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let target = active_keys.borrow_mut().remove(&lane).or_else(|| {
                let pitch = crate::bridge::pitch_for_lane_with_base(lane, roll_base_pitch(&ui))?;
                let track = port.try_project().and_then(|project| {
                    display_track(&ui, &project)
                        .map(|t| t.id)
                        .or_else(|| project.tracks.keys().next().copied())
                })?;
                Some((track, pitch))
            });
            if let Some((track, pitch)) = target {
                let mut host = engine.borrow_mut();
                if host.has_engine() {
                    let _ = host.send_engine_events(&[yeban_engine::ring::EngineEvent::NoteOff {
                        track,
                        pitch,
                    }]);
                }
            }
        }
    });
    ui.on_piano_roll_octave_shift({
        let w = weak.clone();
        let port = Rc::clone(&port);
        move |delta| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            let current = i32::from(roll_base_pitch(&ui));
            if (delta < 0 && current <= 24) || (delta > 0 && current >= 96) {
                return;
            }
            #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
            let next = if delta < 0 {
                (current + delta).max(24) as u8
            } else {
                (current + delta).min(96) as u8
            };
            if next == current as u8 {
                return;
            }
            let range_label = apply_roll_pitch_range(&ui, next);
            let width = slint::ComponentHandle::window(&ui).size().width as f32;
            let scroll = ui.get_roll_scroll_x();
            reproject_roll(&ui, &port, width, scroll);
            ui.set_module_status(format!("钢琴卷帘音域已切换至 {range_label}").into());
            ui.set_module_status_succeeded(true);
        }
    });

    // ⑫ browser-item-load: 写 sidebar-search + 走 wire_sidebar_contents 过滤投影, 并按条目分派加载。
    ui.on_browser_item_load({
        let w = weak.clone();
        move |name| {
            let Some(ui) = w.upgrade() else {
                return;
            };
            ui.set_sidebar_search(name.clone());
            ui.invoke_sidebar_search_changed(name.clone());
            let lower = name.as_str().to_ascii_lowercase();
            let track_id = ui.get_selected_track_index().max(1);
            if lower.contains("pro-q") || lower.contains("eq") || name.as_str().contains("均衡") {
                ui.invoke_track_instrument_change(track_id, "fx:eq".into());
            } else if lower.contains("reverb")
                || lower.contains("verb")
                || name.as_str().contains("混响")
            {
                ui.invoke_track_instrument_change(track_id, "fx:reverb".into());
            } else if lower.contains("sub bass") || lower.contains("808") || lower.contains("bass")
            {
                ui.invoke_track_instrument_change(track_id, "synth:bass".into());
            } else if lower.contains("granulator")
                || lower.contains("wavetable")
                || lower.contains("synth")
            {
                ui.invoke_track_instrument_change(track_id, "synth:hollow".into());
            } else if lower.ends_with(".sfz") {
                ui.invoke_track_instrument_change(
                    track_id,
                    format!("sfz:{}", name.as_str()).into(),
                );
            }
        }
    });

    // ⑬ dock-tab-selected: 写 console-tab(旧控制台与快捷键 F7/F8/F9 的同一读数)。
    // 映射与 app.slint `apply-dock-tab` / `scene::CONSOLE_TABS` 同序:
    // pianoroll=0, mixer=1, devices=2, stacked=3; 未知 tab 名不动 console-tab。
    ui.on_dock_tab_selected({
        let w = weak.clone();
        move |tab| {
            if let Some(ui) = w.upgrade() {
                let index = match tab.as_str() {
                    "pianoroll" | "piano" => 0,
                    "mixer" => 1,
                    "devices" => 2,
                    "stacked" => 3,
                    _ => return,
                };
                ui.set_console_tab(index);
            }
        }
    });

    // ⑭ zone-toggle: .slint 已翻 show-* 开关, 这里把可见区如实写进状态栏读数。
    ui.on_zone_toggle({
        let w = weak.clone();
        move |zone| {
            if let Some(ui) = w.upgrade() {
                let text = format!(
                    "区域 {} · 检查器={} · 片段矩阵={} · 下坞={} · 控制室={}",
                    zone,
                    ui.get_show_left_inspector(),
                    ui.get_show_clip_matrix(),
                    ui.get_show_lower_dock(),
                    ui.get_show_control_room(),
                );
                ui.set_status_selection(text.into());
            }
        }
    });

    // ⑮ monitor-switch: 从引擎读当前输出设备, 写 status-selection(真实设备读数, 非编造)。
    // ⭐ T-FIX-191：MON A/B **真正切换监听总线**（生产路径）。`.slint` 的
    // `mon_a_touch` / `mon_b_touch` 先把组件内的 `active-monitor` 置
    // "main"/"alt" 再调本回调 ⇒ `mon` 就是用户选的那一路；这里先把它写进
    // 引擎的监听总线选择（原子；设备腿上也生效），再读设备名写状态行。
    // 未知名字 ⛔ 不切总线（只显示，不改路由）。
    ui.on_monitor_switch({
        let w = weak.clone();
        let engine = Rc::clone(&engine);
        move |mon| {
            if let Some(ui) = w.upgrade() {
                if let Some(bus) = MonitorBus::from_name(mon.as_str()) {
                    engine.borrow().set_monitor_bus(bus);
                }
                let device = engine
                    .borrow()
                    .device_name()
                    .unwrap_or("(无设备 / 离线)")
                    .to_owned();
                ui.set_status_selection(format!("监听 {} · 引擎输出 {}", mon, device).into());
            }
        }
    });

    // ⑯ hot-swap-buffer-size: 写 buffer-samples(走带条消费) + dsp-cpu-percent 真实换算。
    ui.on_hot_swap_buffer_size({
        let w = weak.clone();
        move |samples| {
            if let Some(ui) = w.upgrade() {
                ui.set_buffer_samples(samples);
                let cpu = match samples {
                    64 => 24,
                    128 => 14,
                    512 => 8,
                    _ => 4,
                };
                ui.set_dsp_cpu_percent(cpu);
            }
        }
    });

    // ⑰ normalize-track-heights: 复位 track-height-percent + 清覆盖 + 重投影。
    ui.on_normalize_track_heights({
        let w = weak.clone();
        let port = Rc::clone(&port);
        move || {
            let Some(ui) = w.upgrade() else {
                return;
            };
            ui.set_track_height_percent(100);
            ui.set_track_height_override_ids(ModelRc::new(VecModel::from(
                Vec::<SharedString>::new(),
            )));
            ui.set_track_height_override_pxs(ModelRc::new(VecModel::from(Vec::<f32>::new())));
            if let Some(project) = port.try_project()
                && let Ok(view_state) = project_with_view_state(&project, &ui)
            {
                apply_view(
                    &ui,
                    &view_state,
                    viewport_width_or_fallback(&ui, crate::scene::DEMO_VIEWPORT_WIDTH as f32),
                    ui.get_roll_scroll_x(),
                );
            }
        }
    });

    // ⑱ open-cmd-palette: 打开命令面板(show-cmd-palette 由 CommandPaletteModal 消费)。
    ui.on_open_cmd_palette({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                ui.set_show_cmd_palette(true);
            }
        }
    });

    // 帮助系统（line/onboarding-help）：手册 / 速查 / 引导 / 课程的全部回调。
    // 放在本函数最后：引导切步要 invoke command-execute，必须等它注册完。
    wire_help_system(ui, &port);
}

/// 帮助系统的回调注册（line/onboarding-help）。落点全在 `crate::help`；
/// 本函数只做弱句柄装配，保证真实装配（main.rs）与无头装配
/// （tests 的 build_main_window 路径）拿到同一套接线。
pub fn wire_help_system(ui: &MainWindow, port: &Rc<UndoPort>) {
    let weak = ui.as_weak();

    ui.on_help_manual_select({
        let w = weak.clone();
        move |index| {
            if let Some(ui) = w.upgrade() {
                crate::help::apply_manual_chapter(&ui, index);
            }
        }
    });
    ui.on_help_manual_close({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                crate::help::close_manual(&ui);
            }
        }
    });
    ui.on_help_shortcuts_close({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                crate::help::close_shortcuts(&ui);
            }
        }
    });
    ui.on_onboarding_next({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                crate::help::onboarding_next(&ui);
            }
        }
    });
    ui.on_onboarding_back({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                crate::help::onboarding_back(&ui);
            }
        }
    });
    ui.on_onboarding_skip({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                crate::help::onboarding_skip(&ui);
            }
        }
    });
    ui.on_onboarding_dismiss_forever({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                crate::help::onboarding_dismiss_forever(&ui);
            }
        }
    });
    ui.on_lessons_start({
        let w = weak.clone();
        let port = Rc::clone(port);
        move |lesson_id| {
            if let Some(ui) = w.upgrade() {
                crate::help::start_lesson(&ui, &port, lesson_id.as_str());
            }
        }
    });
    ui.on_lesson_check_step({
        let w = weak.clone();
        let port = Rc::clone(port);
        move || {
            if let Some(ui) = w.upgrade() {
                crate::help::check_current_step(&ui, &port);
            }
        }
    });
    ui.on_lesson_exit({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                crate::help::exit_lesson(&ui);
            }
        }
    });
    ui.on_lessons_close({
        let w = weak.clone();
        move || {
            if let Some(ui) = w.upgrade() {
                crate::help::close_lessons(&ui);
            }
        }
    });
}

fn parse_key_signature_text(text: &str) -> yeban_model::KeySignature {
    let normalized = text.trim().replace('♯', "#").replace('♭', "b");
    let lower = normalized.to_ascii_lowercase();
    let is_minor_word = lower.contains("minor")
        || normalized.contains("小调")
        || lower
            .split_whitespace()
            .any(|tok| tok == "m" || tok == "min");
    let raw_token = normalized
        .split(|c: char| c.is_whitespace() || c == '大' || c == '小' || c == '(')
        .next()
        .unwrap_or("")
        .to_ascii_lowercase();
    let (tonic, suffix_minor) = if let Some(stem) = raw_token.strip_suffix("minor") {
        (stem, true)
    } else if let Some(stem) = raw_token.strip_suffix("major") {
        (stem, false)
    } else if let Some(stem) = raw_token.strip_suffix("min") {
        (stem, true)
    } else if let Some(stem) = raw_token.strip_suffix("maj") {
        (stem, false)
    } else if raw_token.len() >= 2 && raw_token.ends_with('m') {
        (&raw_token[..raw_token.len() - 1], true)
    } else {
        (raw_token.as_str(), false)
    };
    // 教会调式（T-FIX-446）：调式文本按其父大调写调号。`KeySignature`
    // 只有升降号数 + 大/小调两个字段，调式没有独立字段，故以父大调的
    // `{sharps_flats, is_minor: false}` 表示（MIDI 调号元事件的同一
    // 约定；Aeolian 即自然小调，仍记 `is_minor: true`）。
    // 父大调主音 = 主音下行调式级数对应的半音数。
    if let Some((offset, mode_minor)) = church_mode_parent_major(&lower)
        && let Some(tonic_pc) = tonic_pitch_class(tonic)
    {
        let parent_pc = (tonic_pc + 12 - offset) % 12;
        return yeban_model::KeySignature {
            sharps_flats: major_sharps_flats(parent_pc),
            is_minor: mode_minor,
        };
    }
    let is_minor = is_minor_word || suffix_minor;
    let sharps_flats: i8 = match (tonic, is_minor) {
        ("c", false) | ("a", true) => 0,
        ("g", false) | ("e", true) => 1,
        ("d", false) | ("b", true) => 2,
        ("a", false) | ("f#", true) | ("gb", true) => 3,
        ("e", false) | ("c#", true) | ("db", true) => 4,
        ("b", false) | ("g#", true) => 5,
        ("f#", false) | ("d#", true) => 6,
        ("c#", false) | ("a#", true) => 7,
        ("f", false) | ("d", true) => -1,
        ("bb", false) | ("g", true) => -2,
        ("eb", false) | ("c", true) => -3,
        ("ab", false) | ("f", true) => -4,
        ("db", false) | ("bb", true) => -5,
        ("gb", false) | ("eb", true) => -6,
        ("cb", false) | ("ab", true) => -7,
        _ => 0,
    };
    yeban_model::KeySignature {
        sharps_flats,
        is_minor,
    }
}

/// 教会调式名 →（主音到父大调主音的下行半音数，是否记小调）。
///
/// 检测顺序有讲究：`mixolydian` / `混合利底亚` 含 `lydian` / `利底亚` 子串，
/// 须先判。Ionian 与大调同义、Aeolian 与自然小调同义。
fn church_mode_parent_major(text_lower: &str) -> Option<(u8, bool)> {
    if text_lower.contains("mixolydian") || text_lower.contains("混合利底亚") {
        Some((7, false))
    } else if text_lower.contains("dorian") || text_lower.contains("多利亚") {
        Some((2, false))
    } else if text_lower.contains("phrygian") || text_lower.contains("弗里吉亚") {
        Some((4, false))
    } else if text_lower.contains("lydian") || text_lower.contains("利底亚") {
        Some((5, false))
    } else if text_lower.contains("locrian") || text_lower.contains("洛克里亚") {
        Some((11, false))
    } else if text_lower.contains("aeolian") || text_lower.contains("伊奥利亚") {
        Some((9, true))
    } else if text_lower.contains("ionian") || text_lower.contains("伊奥尼亚") {
        Some((0, false))
    } else {
        None
    }
}

/// 主音拼写 → 音级（C = 0）。未知拼写返回 `None`，调用方回退旧口径。
fn tonic_pitch_class(tonic: &str) -> Option<u8> {
    match tonic {
        "c" => Some(0),
        "c#" | "db" => Some(1),
        "d" => Some(2),
        "d#" | "eb" => Some(3),
        "e" => Some(4),
        "f" => Some(5),
        "f#" | "gb" => Some(6),
        "g" => Some(7),
        "g#" | "ab" => Some(8),
        "a" => Some(9),
        "a#" | "bb" => Some(10),
        "b" | "cb" => Some(11),
        _ => None,
    }
}

/// 大调主音音级 → 调号升降号数（五度圈标准拼写；同音异名取降号拼写，
/// 如音级 1 取 Db 大调 −5 而非 C# 大调 +7）。
fn major_sharps_flats(tonic_pc: u8) -> i8 {
    match tonic_pc {
        0 => 0,   // C
        1 => -5,  // Db
        2 => 2,   // D
        3 => -3,  // Eb
        4 => 4,   // E
        5 => -1,  // F
        6 => 6,   // F#
        7 => 1,   // G
        8 => -4,  // Ab
        9 => 3,   // A
        10 => -2, // Bb
        11 => 5,  // B
        _ => 0,
    }
}

fn view_to_tracks(view: &ViewState) -> Vec<TrackData> {
    view.tracks
        .iter()
        .map(|trk| {
            let next_id = (trk.index + 1) as i32;
            let clips: Vec<&crate::bridge::ClipView> = view
                .clips
                .iter()
                .filter(|c| c.track_index == trk.index)
                .collect();
            let clip1 = clips.first().map_or("", |c| c.clip_name.as_str());
            let clip2 = clips.get(1).map_or("", |c| c.clip_name.as_str());
            let clip3 = clips.get(2).map_or("", |c| c.clip_name.as_str());
            let clip4 = clips.get(3).map_or("", |c| c.clip_name.as_str());

            TrackData {
                id: next_id,
                name: trk.name.clone().into(),
                kind: trk.kind.to_uppercase().into(),
                color: to_color(trk.color_rgb),
                bus: trk.bus_name.clone().into(),
                volume_db: trk.volume_db,
                pan: trk.pan_display.clone().into(),
                muted: trk.mute,
                soloed: trk.solo,
                armed: false,
                // ⭐ 插入槽 = **该轨真实设备链**（`TrackView::devices` 的前三格）。
                // 空链时只保留两种**真实**读数：SFZ 采样器绑定路径（若有）与空串；
                // ⛔ 不再按轨道类型编造 "Wavetable MPE" / "Pro-QLinear 8" /
                // "Glue Comp VCA" —— 工程里没有的设备不该出现在检查器里。
                insert1: trk
                    .devices
                    .first()
                    .map(String::as_str)
                    .or(trk.sampler_path.as_deref())
                    .unwrap_or("")
                    .into(),
                insert2: trk.devices.get(1).map_or("", String::as_str).into(),
                insert3: trk.devices.get(2).map_or("", String::as_str).into(),
                clip1: clip1.into(),
                clip2: clip2.into(),
                clip3: clip3.into(),
                clip4: clip4.into(),
            }
        })
        .collect()
}

/// 音频片段的波形峰值柱数：按**像素宽度**取，约每 3 px 一根，夹在 8..=200。
///
/// 为什么按宽度而不是按拍：绘制层一根柱子占 1 px 以上才画得开；固定 512 根
/// 在窄片段上会挤成一块实心色块（用户 2026-11-16 的「信息过载」反馈同一条取向）。
fn waveform_bins_for_width(width_px: f32) -> usize {
    #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
    let bins = (width_px / 3.0).round() as usize;
    bins.clamp(8, 200)
}

/// 一个片段的峰值数组（非音频 / 无哈希 / 未分析 ⇒ 空）。
fn waveform_peaks_for(clip: &crate::bridge::ClipView) -> Vec<f32> {
    if clip.content != "audio" {
        return Vec::new();
    }
    let Some(hash) = clip.asset_hash.as_deref() else {
        return Vec::new();
    };
    crate::waveform_cache::peaks(hash, waveform_bins_for_width(clip.width))
}

fn view_to_timeline_blocks(view: &ViewState) -> Vec<TimelineBlockData> {
    let mut note_counts: std::collections::BTreeMap<&str, i32> = std::collections::BTreeMap::new();
    for note in &view.notes {
        *note_counts.entry(note.clip_id.as_str()).or_insert(0) += 1;
    }
    view.clips
        .iter()
        .map(|clip| {
            let track_id = (clip.track_index + 1) as i32;
            let track_rgb = view
                .tracks
                .get(clip.track_index)
                .map(|t| t.color_rgb)
                .unwrap_or(crate::bridge::DEFAULT_TRACK_COLOR);
            let col = to_color(track_rgb);
            // 十版片段四色：底 = 轨道色纯色（太浅时统一压暗）、文字
            // 按底色推导、标记/导线 = 轨道色同色相派生，全部在投影层
            // 算（bridge::clip_*_color 唯一实现）。
            let base_rgb = crate::bridge::clip_base_color(track_rgb);
            let marker_rgb = crate::bridge::clip_marker_color(track_rgb);
            let is_audio = clip.content == "audio";
            let note_count = if is_audio {
                0
            } else {
                *note_counts.get(clip.clip_id.as_str()).unwrap_or(&0)
            };
            TimelineBlockData {
                track_id,
                clip_ulid: clip.placement_id.clone().into(),
                label: clip.label.clone().into(),
                start_px: clip.x.max(0.0),
                width_px: clip.width.max(12.0),
                is_audio,
                gain_label: if clip.muted {
                    "Muted".into()
                } else {
                    "0dB".into()
                },
                color: col,
                base_color: to_color(base_rgb),
                text_color: to_color(crate::bridge::clip_text_color(base_rgb)),
                guide_color: to_color(marker_rgb),
                marker_color: to_color(marker_rgb),
                note_count,
                // ⭐ ADR-0076 B1 第二步：按资产哈希查**会话峰值缓存**（`crate::waveform_cache`）。
                // 缓存未就绪 / 字节不在资产池 / 解码失败 ⇒ 空数组 ⇒ 界面画回
                // 「波形待分析 · 示意」的基准线（诚实降级，⛔ 不编形状）。
                waveform_peaks: ModelRc::new(VecModel::from(waveform_peaks_for(clip))),
            }
        })
        .collect()
}

fn view_to_notes(view: &ViewState) -> Vec<PianoRollNote> {
    view.notes
        .iter()
        .map(|note| {
            let pitch_row = note.row.clamp(0, 15);
            let pitch_name = PITCH_NAMES.get(pitch_row as usize).copied().unwrap_or("C4");
            let start_step = (note.x / 42.0).clamp(0.0, 63.0) as i32;
            let step_span = ((note.width / 42.0).ceil() as i32).max(1);
            PianoRollNote {
                id: (note.index + 1) as i32,
                pitch_row,
                pitch_name: pitch_name.into(),
                start_step,
                step_span,
                velocity: note.velocity as i32,
                selected: false,
            }
        })
        .collect()
}

// ============================================================== 缺音源救援面板
//
// 设计来源：Wang 2026-11-19 口径 ——"打开工程缺音源时，如果是内置的就引导下载；
// 不在常见清单里的，按乐器类型**推荐同类**，用户点一下就能换"。所以这个面板
// 只有三种按钮，都是一步到位：
//   * 候选**本机已装**  ⇒ 「换成 X」（立刻提交 `Op::SetTrackSampler`，当下就响）；
//   * 候选**还没装**    ⇒ 「下载 X」（直接开音源管理并筛好那一件，下载完回来再换）；
//   * 原音源在清单里    ⇒ 「下载原音源」。
//
// ⛔ 本面板不下载、不写文件、不碰撤销树以外的东西；它只发动作，真正的提交
// 仍走 [`commit_sampler_binding`]（与混音台 SET/Clear 同一条路，因此撤销/重做、
// 陈旧载荷校验、八度覆盖清理一位不差）。

/// 面板里的行（宿主持有：换掉一件就把那一行摘掉，列表越点越短）。
type MissingRows = std::rc::Rc<std::cell::RefCell<Vec<crate::missing_sounds::MissingSound>>>;

/// 把当前行状态重播进界面（平行数组；三项候选各自 name / path / installed）。
fn publish_missing_rows(ui: &MainWindow, rows: &MissingRows) {
    let items = rows.borrow();
    let mut track_names = Vec::with_capacity(items.len());
    let mut details = Vec::with_capacity(items.len());
    let mut hints = Vec::with_capacity(items.len());
    let mut can_download = Vec::with_capacity(items.len());
    let (mut s1_name, mut s1_path, mut s1_on, mut s1_id) =
        (Vec::new(), Vec::new(), Vec::new(), Vec::new());
    let (mut s2_name, mut s2_path, mut s2_on, mut s2_id) =
        (Vec::new(), Vec::new(), Vec::new(), Vec::new());
    let (mut s3_name, mut s3_path, mut s3_on, mut s3_id) =
        (Vec::new(), Vec::new(), Vec::new(), Vec::new());
    let mut ready = 0usize;
    for item in items.iter() {
        track_names.push(SharedString::from(item.track_name.as_str()));
        // 只显示文件名主干：工程里那条路径是给开发看的，用户只认"哪一件"。
        details.push(SharedString::from(missing_file_label(&item.path)));
        let installed = item
            .suggestions
            .iter()
            .filter(|suggestion| suggestion.installed)
            .count();
        if installed > 0 {
            ready += 1;
        }
        hints.push(SharedString::from(missing_row_hint(item, installed)));
        can_download.push(item.pack_id.is_some());
        let mut slots = [
            (&mut s1_name, &mut s1_path, &mut s1_on, &mut s1_id),
            (&mut s2_name, &mut s2_path, &mut s2_on, &mut s2_id),
            (&mut s3_name, &mut s3_path, &mut s3_on, &mut s3_id),
        ];
        for (index, slot) in slots.iter_mut().enumerate() {
            let (name, path, on, id) = slot;
            match item.suggestions.get(index) {
                Some(suggestion) => {
                    name.push(SharedString::from(suggestion.name.as_str()));
                    path.push(SharedString::from(suggestion.path.as_str()));
                    on.push(suggestion.installed);
                    id.push(SharedString::from(suggestion.id.as_str()));
                }
                None => {
                    name.push(SharedString::from(""));
                    path.push(SharedString::from(""));
                    on.push(false);
                    id.push(SharedString::from(""));
                }
            }
        }
    }
    let summary = if items.is_empty() {
        String::new()
    } else if ready == items.len() {
        format!(
            "有 {} 条轨的音源没装好。下面每条都给了本机已装好的同类音源，点一下立刻换上就能出声。",
            items.len()
        )
    } else if ready > 0 {
        format!(
            "有 {} 条轨的音源没装好，其中 {} 条可以直接换成已装好的同类音源；其余的点「下载」装上再换。",
            items.len(),
            ready
        )
    } else {
        format!(
            "有 {} 条轨的音源没装好，同类音源这台机器上也还没装。点「下载」装好一件，回来我再帮你换。",
            items.len()
        )
    };
    ui.set_missing_sounds_summary(SharedString::from(summary.as_str()));
    ui.set_missing_row_count(i32::try_from(items.len()).unwrap_or(0));
    ui.set_missing_track_names(ModelRc::new(VecModel::from(track_names)));
    ui.set_missing_details(ModelRc::new(VecModel::from(details)));
    ui.set_missing_hints(ModelRc::new(VecModel::from(hints)));
    ui.set_missing_can_download(ModelRc::new(VecModel::from(can_download)));
    ui.set_missing_s1_name(ModelRc::new(VecModel::from(s1_name)));
    ui.set_missing_s1_path(ModelRc::new(VecModel::from(s1_path)));
    ui.set_missing_s1_installed(ModelRc::new(VecModel::from(s1_on)));
    ui.set_missing_s2_name(ModelRc::new(VecModel::from(s2_name)));
    ui.set_missing_s2_path(ModelRc::new(VecModel::from(s2_path)));
    ui.set_missing_s2_installed(ModelRc::new(VecModel::from(s2_on)));
    ui.set_missing_s3_name(ModelRc::new(VecModel::from(s3_name)));
    ui.set_missing_s3_path(ModelRc::new(VecModel::from(s3_path)));
    ui.set_missing_s3_installed(ModelRc::new(VecModel::from(s3_on)));
    ui.set_missing_s1_id(ModelRc::new(VecModel::from(s1_id)));
    ui.set_missing_s2_id(ModelRc::new(VecModel::from(s2_id)));
    ui.set_missing_s3_id(ModelRc::new(VecModel::from(s3_id)));
}

/// 路径 ⇒ 只留文件名主干（`samples/bass/ebass_rel.sfz` ⇒ `ebass_rel`）。
fn missing_file_label(path: &str) -> String {
    let normalized = path.replace('\\', "/");
    let name = normalized.rsplit('/').next().unwrap_or_default();
    let stem = name.strip_suffix(".sfz").unwrap_or(name);
    if stem.is_empty() {
        name.to_owned()
    } else {
        stem.to_owned()
    }
}

/// 一行下面那句提示：说清"这条轨是哪种乐器、有几种走法"。
fn missing_row_hint(item: &crate::missing_sounds::MissingSound, installed: usize) -> String {
    if item.suggestions.is_empty() {
        return format!(
            "这件的乐器类型是「{}」，但这台机器和清单里都没有可替换的同类。你可以自己装回原音源，或先用别的音源顶一下。",
            item.kind.label()
        );
    }
    if installed == 0 {
        return format!(
            "认作「{}」。同类音源本机还没装，选一件下载后就能立刻换上。",
            item.kind.label()
        );
    }
    format!(
        "认作「{}」。{} 件同类候选里有 {} 件都在这台机器上，点一下立刻换上。",
        item.kind.label(),
        item.suggestions.len(),
        installed
    )
}

/// 换上一条候选音源（一次点击的完整闭环：提交 + 回执）。
///
/// 返回 `true` = 真的提交了（界面上那一行可以摘掉）。
fn swap_track_sampler(
    ui: &MainWindow,
    port: &UndoPort,
    index: i32,
    path: &str,
    name: &str,
) -> bool {
    if !commit_sampler_binding(ui, port, index, Some(path), "swap missing sound") {
        return false;
    }
    report_notice(
        ui,
        &MissingSoundsNotice::SwappedOne {
            name: name.to_string(),
        }
        .text_in(current_language()),
        false,
    );
    true
}

/// 开音源管理并**筛好**一件（"去下载"的那条腿）。顺序是契约：先开、再写搜索、最后重播。
///
/// ⭐ 顺带把救援面板**收起来**：两个面板叠着是"用户点了下载却看不见下载进度"的根因。
/// 行状态一位不丢（`RESCUE_SINK` 还在），关掉音源管理时若还有没解决的轨，面板自己回来。
fn open_library_for(ui: &MainWindow, seed: &str, status: &str) {
    ui.set_missing_sounds_open(false);
    ui.invoke_open_sound_library();
    ui.set_sound_library_search(SharedString::from(seed));
    ui.set_sound_library_status(SharedString::from(status));
    ui.set_sound_library_status_is_error(false);
    ui.invoke_sound_library_filter_changed(SharedString::from(seed));
}

/// 一条"下载完就换到轨上"的待办（用户点了「下载 X」那一刻记下）。
#[derive(Clone, Debug)]
struct PendingBind {
    track_index: i32,
    pack_id: String,
    /// 界面上那件音源的显示名（回执里要用）。
    name: String,
}

/// 救援面板的**活引用**：下载完成那一跳（音源管理那边）拿它继续把轨换掉。
///
/// 为什么放线程局部而不是字段：`wire_sound_library_dialog` 与
/// [`wire_missing_sounds_dialog`] 是两个**各自独立**的装配入口，谁也不知道对方。
/// 两者的回调都跑在 Slint 事件循环线程上，因此这里不需要锁、也不能用 `Rc` 跨线程。
struct RescueSink {
    port: Rc<UndoPort>,
    rows: MissingRows,
    pending: Vec<PendingBind>,
}

thread_local! {
    static RESCUE_SINK: RefCell<Option<RescueSink>> = const { RefCell::new(None) };
}

/// 记下"这条轨在等这件音源装好"（同一条轨只留最新一件：用户改主意了就按新的来）。
fn remember_pending_bind(track_index: i32, pack_id: &str, name: &str) {
    RESCUE_SINK.with(|slot| {
        let Ok(mut guard) = slot.try_borrow_mut() else {
            return;
        };
        let Some(sink) = guard.as_mut() else {
            return;
        };
        sink.pending
            .retain(|pending| pending.track_index != track_index);
        sink.pending.push(PendingBind {
            track_index,
            pack_id: pack_id.to_owned(),
            name: name.to_owned(),
        });
    });
}

/// 救援面板里还有没解决的轨吗？（音源管理关闭时要据此把面板还回去）
fn rescue_rows_remaining() -> bool {
    RESCUE_SINK.with(|slot| {
        slot.try_borrow()
            .ok()
            .and_then(|guard| guard.as_ref().map(|sink| !sink.rows.borrow().is_empty()))
            .unwrap_or(false)
    })
}

/// 一个音源包装好了 ⇒ 把**等着它的那些轨**立刻换上（用户点过一次「下载」就不该再点第二次）。
///
/// 由 `wire_sound_library_dialog` 的排空跳在**下载成功之后**调用；失败不调（没装好就别换）。
/// 没有救援待办 ⇒ 什么也不做（普通下载不受影响）。
pub fn rescue_after_pack_installed(ui: &MainWindow, pack_id: &str) {
    RESCUE_SINK.with(|slot| {
        let Ok(mut guard) = slot.try_borrow_mut() else {
            return;
        };
        let Some(sink) = guard.as_mut() else {
            return;
        };
        let targets: Vec<PendingBind> = sink
            .pending
            .iter()
            .filter(|pending| pending.pack_id == pack_id)
            .cloned()
            .collect();
        if targets.is_empty() {
            return;
        }
        sink.pending.retain(|pending| pending.pack_id != pack_id);
        let roots = crate::sfz_load::SfzRoots::none();
        let mut swapped: Vec<String> = Vec::new();
        // T-FIX-344：先记下各待换轨在**当前行表里的下标**（= 对话框 `for` 的行号；
        // 行一删下标就变，事后算不出来）。只记真正换上的 —— 没换上的行还在，
        // 焦点不用挪。
        let pre_rows: Vec<i32> = sink
            .rows
            .borrow()
            .iter()
            .map(|item| item.track_index)
            .collect();
        let mut deleted_rows: Vec<i32> = Vec::new();
        for target in targets {
            let track_name = sink
                .rows
                .borrow()
                .iter()
                .find(|item| item.track_index == target.track_index)
                .map(|item| item.track_name.clone())
                .unwrap_or_default();
            let Some(path) = crate::missing_sounds::installed_path(&target.pack_id, roots) else {
                report_notice(
                    ui,
                    &MissingSoundsNotice::NoUsableSfz {
                        name: target.name.clone(),
                    }
                    .text_in(current_language()),
                    true,
                );
                continue;
            };
            if !swap_track_sampler(ui, &sink.port, target.track_index, &path, &target.name) {
                continue;
            }
            if let Some(pos) = pre_rows
                .iter()
                .position(|&index| index == target.track_index)
            {
                deleted_rows.push(i32::try_from(pos).unwrap_or(0));
            }
            sink.rows
                .borrow_mut()
                .retain(|item| item.track_index != target.track_index);
            if track_name.is_empty() {
                swapped.push(target.name.clone());
            } else {
                swapped.push(format!("{}（{track_name}）", target.name));
            }
        }
        if swapped.is_empty() {
            return;
        }
        // T-FIX-344：宿主删行前先挪焦点 —— 与对话框内 swap 守卫（T-FIX-333）
        // 同一锚点（✕）同一时机（行消失之前）。救援是后台完成的：用户可能在
        // 音源管理关掉、面板还回来之后又 Tab 回被删的那一行；不挪，
        // `focused-row-slot` 就指着不存在的行（死焦点），之后 Tab 的读数与
        // 轮转全错。只在对话框还开着、且焦点确实在被删行里时挪；焦点在幸存
        // 行 / ✕ / 「先不管」上 ⇒ 不动。
        // T-FIX-427：同一次读数顺带记下删行前的焦点槽位 —— `publish_missing_rows`
        // 会换掉整组行数组、重建 `for` 行元素，事后读到的已是新表下的读数，
        // 无法反推焦点原来在哪一行；重基（见下文）必须用删行前的值。
        let focused_before = if ui.get_missing_sounds_open() {
            ui.get_missing_sounds_focused_control()
        } else {
            -1
        };
        if ui.get_missing_sounds_open()
            && deleted_rows.iter().any(|&row| {
                focused_before >= 100 + row * 10 && focused_before < 100 + (row + 1) * 10
            })
        {
            ui.invoke_focus_missing_sounds_dialog();
        }
        let empty = sink.rows.borrow().is_empty();
        publish_missing_rows(ui, &sink.rows);
        // T-FIX-427：焦点在幸存行上时按新行号重基。344 守卫已把被删行上的
        // 焦点挪到 ✕，这里只处理幸存行：删掉的行若在焦点行之上，同一行
        // 新下标 = 旧下标 − 上方已删行数，格内槽位不变。焦点在 ✕ / 「先不管」
        // / 被删行上时不动（值 < 100，或行号落在已删区间）。
        if focused_before >= 100 {
            let row = (focused_before - 100) / 10;
            let cell = (focused_before - 100) % 10;
            let on_deleted = deleted_rows.contains(&row);
            if !on_deleted {
                let above = deleted_rows
                    .iter()
                    .filter(|&&deleted| deleted < row)
                    .count();
                if above > 0 {
                    ui.invoke_rebase_missing_sounds_focused_row_slot(
                        100 + (row - i32::try_from(above).unwrap_or(0)) * 10 + cell,
                    );
                }
            }
        }
        if empty {
            ui.set_missing_sounds_open(false);
            // 都换好了 ⇒ 那条"音源没装好"的红字不再成立，收掉它。
            ui.set_engine_error(SharedString::from(""));
        }
        report_notice(
            ui,
            &MissingSoundsNotice::Swapped { swapped }.text_in(current_language()),
            false,
        );
    });
}

/// 接线：把"打开工程时发现的缺失"交给救援面板，并接管它的三个动作。
///
/// ⚠ 只能在**装配阶段**调一次（`ui.on_missing_*` 是单槽回调）；
/// `items` 为空 ⇒ 面板保持关闭，默认帧一位不变。
pub fn wire_missing_sounds_dialog(
    ui: &MainWindow,
    port: Rc<UndoPort>,
    items: Vec<crate::missing_sounds::MissingSound>,
) {
    let rows: MissingRows = Rc::new(RefCell::new(items));
    publish_missing_rows(ui, &rows);
    // T-FIX-182：有缺失 ⇒ 打开即取焦（与五只已修模态同一顺序；空 ⇒ 不开也不取焦）。
    let should_open = !rows.borrow().is_empty();
    ui.set_missing_sounds_open(should_open);
    if should_open {
        ui.invoke_focus_missing_sounds_dialog();
    }
    // 把"活引用"交给下载完成那一跳：点了「下载」之后**不用再点第二次**。
    RESCUE_SINK.with(|slot| {
        *slot.borrow_mut() = Some(RescueSink {
            port: Rc::clone(&port),
            rows: Rc::clone(&rows),
            pending: Vec::new(),
        });
    });

    // ---- 换成同类（已装的候选）---------------------------------------------
    ui.on_missing_swap_suggested({
        let weak = ui.as_weak();
        let rows = Rc::clone(&rows);
        let port = Rc::clone(&port);
        move |index, path, name| {
            let Some(ui) = weak.upgrade() else {
                debug_assert!(false, "MainWindow 在回调执行期间被销毁");
                return;
            };
            let Some(row) = rows
                .borrow()
                .get(usize::try_from(index).unwrap_or(usize::MAX))
                .cloned()
            else {
                return;
            };
            if !swap_track_sampler(&ui, &port, row.track_index, path.as_str(), name.as_str()) {
                return;
            }
            // T-ISS-MWVUOZCU：删行前先记下焦点槽位 —— `publish_missing_rows` 会换掉
            // 整组行数组、重建 `for` 行元素，事后读到的已是新表下的读数，无法反推
            // 焦点原来在哪一行；重基（见下文）必须用删行前的值。（T-FIX-427 同款。）
            let focused_before = ui.get_missing_sounds_focused_control();
            // 换好了 ⇒ 这一行不再"缺"，列表越点越短；全清 ⇒ 面板自己走人。
            rows.borrow_mut()
                .retain(|item| item.track_index != row.track_index);
            let empty = rows.borrow().is_empty();
            publish_missing_rows(&ui, &rows);
            // T-ISS-MWVUOZCU：焦点在幸存行上时按新行号重基。被删行上的焦点已由
            // 对话框内 swap 守卫（T-FIX-333）在发 swap 前挪到 ✕，这里只处理幸存行：
            // 被删行在焦点行之上 ⇒ 同一行新下标 = 旧下标 − 1，格内槽位不变。
            // 焦点在 ✕ / 「先不管」/ 被删行上时不动（值 < 100，或行号等于被删行）。
            // 全清 ⇒ 面板随即关闭、焦点复位回快捷键层，也不动。
            if !empty && focused_before >= 100 {
                let row = (focused_before - 100) / 10;
                let cell = (focused_before - 100) % 10;
                if row > index {
                    ui.invoke_rebase_missing_sounds_focused_row_slot(100 + (row - 1) * 10 + cell);
                }
            }
            if empty {
                ui.set_missing_sounds_open(false);
                ui.set_engine_error(SharedString::from(""));
                // ISS-MWUOMH3B-40521F：最后一行换完面板自己走人时，焦点也要复位回
                // 快捷键层（与 `on_missing_close` 同一写法；否则焦点停在已关对话框
                // 的 ✕ 上）。其余两处自动关窗点不补：`rescue_after_pack_installed`
                // 与音源管理"用到当前轨"都发生在音源管理打开、焦点已在馆内时，
                // 关的只是早已收起的救援面板，复位会把焦点从馆里拽走。
                ui.invoke_focus_shortcut_layer();
                report_notice(
                    &ui,
                    &MissingSoundsNotice::AllSwapped.text_in(current_language()),
                    false,
                );
            }
        }
    });

    // ---- 候选还没装 ⇒ 去下载那一件（不替用户下，只把路铺到"点下载"）------------
    ui.on_missing_open_pack({
        let weak = ui.as_weak();
        let rows = Rc::clone(&rows);
        move |index, pack_id, pack_name| {
            let Some(ui) = weak.upgrade() else {
                return;
            };
            if pack_id.is_empty() {
                return;
            }
            let Some(row) = rows
                .borrow()
                .get(usize::try_from(index).unwrap_or(usize::MAX))
                .cloned()
            else {
                return;
            };
            // ⭐ 记下"这条轨在等这件音源"：装好那一刻自动换上（见
            // [`rescue_after_pack_installed`]），用户不用回来再点第二次。
            remember_pending_bind(row.track_index, pack_id.as_str(), pack_name.as_str());
            let status = MissingSoundsOpenStatus::PackNotDownloaded {
                pack_name: pack_name.to_string(),
                track_name: row.track_name.clone(),
            }
            .text_in(current_language());
            open_library_for(&ui, pack_id.as_str(), status.as_str());
        }
    });

    // ---- 就想要原音源 ⇒ 开音源管理、按它的包 id 筛好 --------------------------
    ui.on_missing_download_original({
        let weak = ui.as_weak();
        let rows = Rc::clone(&rows);
        move |index| {
            let Some(ui) = weak.upgrade() else {
                return;
            };
            let Some(row) = rows
                .borrow()
                .get(usize::try_from(index).unwrap_or(usize::MAX))
                .cloned()
            else {
                return;
            };
            let Some(pack_id) = row.pack_id.clone() else {
                report_notice(
                    &ui,
                    &MissingSoundsNotice::NotInCatalog.text_in(current_language()),
                    true,
                );
                return;
            };
            let name = row.pack_name.clone().unwrap_or_else(|| pack_id.clone());
            remember_pending_bind(row.track_index, pack_id.as_str(), name.as_str());
            let status = MissingSoundsOpenStatus::OriginalPack {
                name,
                track_name: row.track_name.clone(),
            }
            .text_in(current_language());
            open_library_for(&ui, pack_id.as_str(), status.as_str());
        }
    });

    // ---- 先不管 ------------------------------------------------------------
    // T-FIX-182：关窗 ⇒ 焦点复位回快捷键层（与音源管理的 `on_close_sound_library`
    // 同一写法；`Esc` / ✕ 都走这条回调）。
    ui.on_missing_close({
        let weak = ui.as_weak();
        move || {
            let Some(ui) = weak.upgrade() else {
                return;
            };
            let was_open = ui.get_missing_sounds_open();
            ui.set_missing_sounds_open(false);
            if was_open {
                ui.invoke_focus_shortcut_layer();
            }
        }
    });
}

// ===========================================================================
// 插件与 ARA 面板（T-FIX-83）
// ===========================================================================
//
// 五条 GUI 入口的宿主侧：扫描与渲染在后台线程，结果经 channel 回 UI 线程；
// 装载走 `UndoPort::commit_ops` 的普通 GUI 编辑路径；ARA 会话 registry 由本
// 面板持有（与 MCP 的 `Domain` registry 互不共享，二者都是同一 `yeban-plugin-host`
// 的调用者）。
//
// ⛔ 本文件不复制插件扫描 / 验证加载 / ARA 打开的实现：它们全在
// `plugin_panel.rs` → `yeban-plugin-host`。

#[derive(Clone, Debug)]
struct AraRowState {
    id: String,
    factory: String,
    state: String,
    detail: String,
}

enum AraRenderMessage {
    Done {
        generation: u64,
        id: String,
        session: yeban_plugin_host::AraSession,
        summary: crate::plugin_panel::AraRenderSummary,
    },
    Failed {
        generation: u64,
        id: String,
        session: yeban_plugin_host::AraSession,
        error: String,
    },
}

impl AraRenderMessage {
    /// 发起渲染时的工程代际（T-FIX-349）。换工程后旧代际的消息一律作废。
    fn generation(&self) -> u64 {
        match self {
            Self::Done { generation, .. } | Self::Failed { generation, .. } => *generation,
        }
    }
}

#[derive(Default)]
struct PluginPanelState {
    /// ⭐ 工程代际（T-FIX-349）：打开 / 新建工程时 +1；ARA 会话与在飞渲染都绑定
    /// 这个代际，旧代际的 sessionId / 回调结果不得进入新工程。
    generation: u64,
    rows: Vec<crate::plugin_panel::PluginRow>,
    selected: Option<usize>,
    scan_rx: Option<std::sync::mpsc::Receiver<crate::plugin_panel::ScanReport>>,
    ara: crate::plugin_panel::AraRegistry,
    ara_rows: Vec<AraRowState>,
    selected_ara: Option<usize>,
    render_rx: Option<std::sync::mpsc::Receiver<AraRenderMessage>>,
}

thread_local! {
    /// 本线程最后一个插件 / ARA 面板状态（生产单窗口；判据每线程一个）。
    static PLUGIN_PANEL_STATE: RefCell<Option<Rc<RefCell<PluginPanelState>>>> =
        const { RefCell::new(None) };
}

/// ⭐ **工程边界：作废全部 ARA 会话**（T-FIX-349）。
///
/// open_archive_runtime 在换会话成功后调用（打开 / 新建 / 模板副本都走那里）：
/// 代际 +1，清空 ara / ara_rows / selected_ara，丢弃在飞渲染的接收端，并把界面
/// 读数复位。与 MCP Domain::reset_history 的 ara_sessions.clear() +
/// ara_next_id = 1 是同一条"工程边界清会话"语义。
///
/// 旧 sessionId 清空后不再存在于 registry ⇒ 查询/渲染都找不到；在飞渲染的回调
/// 带旧代际，drain 时直接丢弃，⛔ 不会把旧工程会话 restore 回新工程。
pub fn reset_plugin_panel_for_project_switch(ui: &MainWindow) {
    let Some(state) = PLUGIN_PANEL_STATE.with(|slot| slot.borrow().clone()) else {
        return;
    };
    {
        let mut state_borrow = state.borrow_mut();
        state_borrow.generation = state_borrow.generation.wrapping_add(1);
        state_borrow.ara.clear();
        state_borrow.ara_rows.clear();
        state_borrow.selected_ara = None;
        state_borrow.render_rx = None;
    }
    let empty: Vec<crate::ui::AraRowData> = Vec::new();
    ui.set_ara_rows(ModelRc::new(VecModel::from(empty)));
    ui.set_ara_selected_row(-1);
    ui.set_ara_status("".into());
    ui.set_ara_query_result("".into());
    ui.set_ara_result("".into());
    ui.set_ara_progress(0.0);
}

fn plugin_ui_rows(rows: &[crate::plugin_panel::PluginRow]) -> Vec<crate::ui::PluginRowData> {
    rows.iter()
        .map(|row| crate::ui::PluginRowData {
            name: row.title().into(),
            meta: row.meta().into(),
            state: row.state().into(),
            path: row.path.clone().into(),
            class_id: row.class_id.clone().into(),
            kind: row.kind.clone().into(),
            usable: row.usable,
            ara: row.ara,
        })
        .collect()
}

fn ara_ui_rows(rows: &[AraRowState]) -> Vec<crate::ui::AraRowData> {
    rows.iter()
        .map(|row| crate::ui::AraRowData {
            id: row.id.clone().into(),
            factory: row.factory.clone().into(),
            state: row.state.clone().into(),
            detail: row.detail.clone().into(),
        })
        .collect()
}

fn plugin_set_rows(
    ui: &MainWindow,
    state: &mut PluginPanelState,
    report: crate::plugin_panel::ScanReport,
) {
    let first_usable = report.rows.iter().position(|row| row.usable);
    state.rows = report.rows;
    state.selected = first_usable;
    ui.set_plugin_rows(ModelRc::new(VecModel::from(plugin_ui_rows(&state.rows))));
    ui.set_plugin_selected_row(first_usable.map_or(-1, |index| index as i32));
    ui.set_plugin_scan_status(
        format!(
            "扫描 {} 个类：{} 可用，{} 失败",
            state.rows.len(),
            report.usable,
            report.failed
        )
        .into(),
    );
    if let Some(index) = first_usable {
        ui.set_ara_plugin_path(state.rows[index].path.clone().into());
    }
}

fn plugin_target_label(ui: &MainWindow, port: Option<&UndoPort>) -> String {
    let Some(port) = port else {
        return "（无活跃工程）".to_owned();
    };
    let Some(project) = port.try_project() else {
        return "（无活跃工程）".to_owned();
    };
    display_track(ui, &project)
        .map(|track| track.name.clone())
        .unwrap_or_else(|| "（没有选中音轨）".to_owned())
}

fn ara_state_from_query(query: &str) -> String {
    if query.contains("分析 可用") {
        "分析可用".to_owned()
    } else if query.contains("分析 未完成") {
        "分析未完成".to_owned()
    } else {
        "已绑定".to_owned()
    }
}

/// 插件与 ARA 面板的唯一接线点（`main.rs::wire_callbacks` 调用）。
///
/// `port` 允许 `None`：没有撤销会话时扫描 / 查询 / 绑定 / 渲染仍可用，只有
/// “装载到轨”会如实拒绝（与鼓机弹窗同一条纪律，⛔ 不静默降级）。
pub fn wire_plugin_panel(ui: &MainWindow, port: Option<Rc<UndoPort>>) {
    let weak = ui.as_weak();
    let state = Rc::new(RefCell::new(PluginPanelState::default()));
    PLUGIN_PANEL_STATE.with(|slot| *slot.borrow_mut() = Some(Rc::clone(&state)));

    ui.on_open_plugin_panel({
        let weak = weak.clone();
        let port = port.clone();
        let state = Rc::clone(&state);
        move || {
            let Some(ui) = weak.upgrade() else {
                return;
            };
            ui.set_plugin_panel_open(true);
            ui.set_plugin_target_label(plugin_target_label(&ui, port.as_deref()).into());
            ui.set_plugin_error("".into());
            ui.set_plugin_notice(crate::plugin_panel::PLUGIN_REGISTRATION_NOTE.into());
            if ui.get_ara_out_path().is_empty() {
                ui.set_ara_out_path(
                    std::env::temp_dir()
                        .join("yeban-ara-render.wav")
                        .to_string_lossy()
                        .to_string()
                        .into(),
                );
            }
            let state_borrow = state.borrow();
            if let Some(index) = state_borrow.selected
                && let Some(row) = state_borrow.rows.get(index)
            {
                ui.set_ara_plugin_path(row.path.clone().into());
            }
        }
    });

    ui.on_plugin_close({
        let weak = weak.clone();
        move || {
            if let Some(ui) = weak.upgrade() {
                ui.set_plugin_panel_open(false);
            }
        }
    });

    ui.on_plugin_scan({
        let weak = weak.clone();
        let state = Rc::clone(&state);
        move || {
            let Some(ui) = weak.upgrade() else {
                return;
            };
            if state.borrow().scan_rx.is_some() {
                ui.set_plugin_scan_status("扫描尚未结束…".into());
                return;
            }
            let paths = ui.get_plugin_scan_paths().to_string();
            let (tx, rx) = std::sync::mpsc::channel();
            state.borrow_mut().scan_rx = Some(rx);
            ui.set_plugin_scan_status("扫描中…（后台读取本机插件目录）".into());
            ui.set_plugin_error("".into());
            let worker_weak = weak.clone();
            std::thread::spawn(move || {
                let report = crate::plugin_panel::scan(&paths);
                let _ = tx.send(report);
                let _ = worker_weak.upgrade_in_event_loop(|ui| {
                    ui.invoke_plugin_scan_drain_requested();
                });
            });
        }
    });

    ui.on_plugin_scan_drain_requested({
        let weak = weak.clone();
        let state = Rc::clone(&state);
        move || {
            let Some(ui) = weak.upgrade() else {
                return;
            };
            let received = {
                let mut state = state.borrow_mut();
                let Some(rx) = state.scan_rx.as_ref() else {
                    return;
                };
                match rx.try_recv() {
                    Ok(report) => {
                        state.scan_rx = None;
                        Some(Ok(report))
                    }
                    Err(std::sync::mpsc::TryRecvError::Empty) => None,
                    Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                        state.scan_rx = None;
                        Some(Err(()))
                    }
                }
            };
            match received {
                Some(Ok(report)) => {
                    plugin_set_rows(&ui, &mut state.borrow_mut(), report);
                }
                Some(Err(())) => {
                    ui.set_plugin_scan_status("扫描线程异常结束；没有结果可显示".into());
                }
                None => {}
            }
        }
    });

    ui.on_plugin_select({
        let weak = weak.clone();
        let state = Rc::clone(&state);
        move |index: i32| {
            let Some(ui) = weak.upgrade() else {
                return;
            };
            let Ok(index) = usize::try_from(index) else {
                return;
            };
            let state_borrow = state.borrow();
            let Some(row) = state_borrow.rows.get(index) else {
                return;
            };
            let path = row.path.clone();
            let title = row.title();
            drop(state_borrow);
            // 选中态必须同时写回装载侧读的 `selected`：只改 UI 属性会让「装载」永远用
            // 扫描后的默认可用行（首个可用插件），点别的行看似选中、实际装的是另一支。
            state.borrow_mut().selected = Some(index);
            ui.set_plugin_selected_row(index as i32);
            ui.set_ara_plugin_path(path.into());
            ui.set_plugin_error("".into());
            ui.set_plugin_notice(format!("已选中: {title}").into());
        }
    });

    ui.on_plugin_load({
        let weak = weak.clone();
        let port = port.clone();
        let state = Rc::clone(&state);
        move || {
            let Some(ui) = weak.upgrade() else {
                return;
            };
            let Some(port) = port.as_deref() else {
                ui.set_plugin_error("没有撤销会话，插件装载未提交".into());
                return;
            };
            let row = {
                let state_borrow = state.borrow();
                state_borrow
                    .selected
                    .and_then(|index| state_borrow.rows.get(index))
                    .cloned()
            };
            let Some(row) = row else {
                ui.set_plugin_error("请先选择一个可用的插件".into());
                return;
            };
            if !row.usable {
                ui.set_plugin_error(format!("插件不可用，拒绝装载: {}", row.state()).into());
                return;
            }
            let Some(project) = port.try_project() else {
                ui.set_plugin_error("没有活跃工程，插件装载未提交".into());
                return;
            };
            let Some(track) = display_track(&ui, &project) else {
                ui.set_plugin_error("当前没有可装载的轨道".into());
                return;
            };
            let track_id = track.id;
            let track_name = track.name.clone();
            let slot_index = track.devices.len();
            ui.set_plugin_error("".into());
            ui.set_plugin_notice("正在验证加载插件…".into());
            let jsfx_path = ui.get_plugin_jsfx_path().to_string();
            let device = if jsfx_path.trim().is_empty() {
                match crate::plugin_panel::load_device(
                    &row.path,
                    Some(row.class_name.as_str()),
                    &row.kind,
                ) {
                    Ok(device) => device,
                    Err(error) => {
                        ui.set_plugin_error(error.into());
                        ui.set_plugin_notice("".into());
                        return;
                    }
                }
            } else {
                match crate::plugin_panel::load_device_with_jsfx(
                    &row.path,
                    Some(row.class_name.as_str()),
                    &row.kind,
                    &jsfx_path,
                ) {
                    Ok(device) => device,
                    Err(error) => {
                        ui.set_plugin_error(error.into());
                        ui.set_plugin_notice("".into());
                        return;
                    }
                }
            };
            let device_name = device.name.clone();
            let ops = vec![yeban_model::Op::InsertDevice {
                track_id,
                slot_index,
                device,
            }];
            let commit_label = format!("load plugin: {device_name} -> {track_name}");
            match port.commit_ops(now_ms(), &commit_label, ops) {
                Ok(_) => {
                    ui.set_plugin_notice(
                        format!(
                            "已装载 {device_name} → {track_name}（{}）",
                            crate::plugin_panel::PLUGIN_REGISTRATION_NOTE
                        )
                        .into(),
                    );
                    ui.set_plugin_target_label(track_name.into());
                    refresh_undo_window(&ui, port, true);
                }
                Err(error) => {
                    ui.set_plugin_error(format!("插件装载提交被拒绝: {error}").into());
                    ui.set_plugin_notice("".into());
                }
            }
        }
    });

    ui.on_ara_select({
        let weak = weak.clone();
        let state = Rc::clone(&state);
        move |index: i32| {
            let Some(ui) = weak.upgrade() else {
                return;
            };
            let Ok(index) = usize::try_from(index) else {
                return;
            };
            let state_borrow = state.borrow();
            let Some(row) = state_borrow.ara_rows.get(index) else {
                return;
            };
            ui.set_ara_selected_row(index as i32);
            ui.set_ara_status(format!("已选中会话 {}", row.id).into());
            ui.set_ara_result(row.detail.clone().into());
        }
    });

    ui.on_ara_bind({
        let weak = weak.clone();
        let state = Rc::clone(&state);
        move || {
            let Some(ui) = weak.upgrade() else {
                return;
            };
            let plugin_path = ui.get_ara_plugin_path().to_string();
            let wav_path = ui.get_ara_wav_path().to_string();
            if plugin_path.trim().is_empty() {
                ui.set_ara_status("`pluginPath` 是必填实参".into());
                return;
            }
            if wav_path.trim().is_empty() {
                ui.set_ara_status("`wavPath` 是必填实参".into());
                return;
            }
            let tempo = match crate::plugin_panel::parse_tempo(ui.get_ara_tempo().as_str()) {
                Ok(value) => value,
                Err(error) => {
                    ui.set_ara_status(error.into());
                    return;
                }
            };
            let loops = match crate::plugin_panel::parse_loop_iterations(ui.get_ara_loop().as_str())
            {
                Ok(value) => value,
                Err(error) => {
                    ui.set_ara_status(error.into());
                    return;
                }
            };
            let summary = {
                let mut state_borrow = state.borrow_mut();
                match state_borrow.ara.bind(
                    plugin_path.as_str(),
                    None,
                    wav_path.as_str(),
                    tempo,
                    loops,
                    ui.get_ara_muted(),
                ) {
                    Ok(summary) => summary,
                    Err(error) => {
                        ui.set_ara_status(error.into());
                        ui.set_ara_result("".into());
                        return;
                    }
                }
            };
            let mut state_borrow = state.borrow_mut();
            state_borrow.ara_rows.push(AraRowState {
                id: summary.id.clone(),
                factory: format!(
                    "{} v{} · {}Hz · {} 帧",
                    summary.factory_name,
                    summary.factory_version,
                    summary.sample_rate,
                    summary.frames
                ),
                state: "已绑定".to_owned(),
                detail: String::new(),
            });
            let index = state_borrow.ara_rows.len() - 1;
            state_borrow.selected_ara = Some(index);
            ui.set_ara_rows(ModelRc::new(VecModel::from(ara_ui_rows(
                &state_borrow.ara_rows,
            ))));
            ui.set_ara_selected_row(index as i32);
            ui.set_ara_status(format!("已绑定 {}", summary.id).into());
            ui.set_ara_query_result("".into());
            ui.set_ara_result(
                format!(
                    "{} v{} · {} 帧 @ {} Hz · 循环 {} · {}",
                    summary.factory_name,
                    summary.factory_version,
                    summary.frames,
                    summary.sample_rate,
                    summary.loop_iterations,
                    if summary.muted { "静音" } else { "不静音" }
                )
                .into(),
            );
        }
    });

    ui.on_ara_query({
        let weak = weak.clone();
        let state = Rc::clone(&state);
        move || {
            let Some(ui) = weak.upgrade() else {
                return;
            };
            let id = {
                let state_borrow = state.borrow();
                state_borrow
                    .selected_ara
                    .and_then(|index| state_borrow.ara_rows.get(index))
                    .map(|row| row.id.clone())
            };
            let Some(id) = id else {
                ui.set_ara_status("请先选择一个 ARA 会话".into());
                return;
            };
            let query = {
                let state_borrow = state.borrow();
                match state_borrow.ara.query(&id) {
                    Ok(query) => query,
                    Err(error) => {
                        ui.set_ara_status(error.into());
                        ui.set_ara_result("".into());
                        return;
                    }
                }
            };
            let mut state_borrow = state.borrow_mut();
            let new_state = ara_state_from_query(&query);
            if let Some(index) = state_borrow.selected_ara
                && let Some(row) = state_borrow.ara_rows.get_mut(index)
            {
                row.state = new_state;
                row.detail = query.clone();
            }
            ui.set_ara_rows(ModelRc::new(VecModel::from(ara_ui_rows(
                &state_borrow.ara_rows,
            ))));
            ui.set_ara_status("查询完成".into());
            ui.set_ara_query_result(query.into());
        }
    });

    ui.on_ara_render({
        let weak = weak.clone();
        let state = Rc::clone(&state);
        move || {
            let Some(ui) = weak.upgrade() else {
                return;
            };
            if state.borrow().render_rx.is_some() {
                ui.set_ara_status("ARA 渲染尚未结束…".into());
                return;
            }
            let (id, session) = {
                let mut state_borrow = state.borrow_mut();
                let Some(index) = state_borrow.selected_ara else {
                    ui.set_ara_status("请先选择一个 ARA 会话".into());
                    return;
                };
                let Some(row) = state_borrow.ara_rows.get(index) else {
                    ui.set_ara_status("请先选择一个 ARA 会话".into());
                    return;
                };
                let id = row.id.clone();
                match state_borrow.ara.take(&id) {
                    Some(session) => (id, session),
                    None => {
                        ui.set_ara_status(format!("没有 ARA 会话 `{id}`").into());
                        return;
                    }
                }
            };
            let block_frames =
                match crate::plugin_panel::parse_block_frames(ui.get_ara_block_frames().as_str()) {
                    Ok(value) => value,
                    Err(error) => {
                        let mut state_borrow = state.borrow_mut();
                        state_borrow.ara.restore(id, session);
                        ui.set_ara_status(error.into());
                        return;
                    }
                };
            let out_path = ui.get_ara_out_path().to_string();
            if out_path.trim().is_empty() {
                let mut state_borrow = state.borrow_mut();
                state_borrow.ara.restore(id, session);
                ui.set_ara_status("`outPath` 是必填实参".into());
                return;
            }
            // ⭐ T-FIX-349：渲染消息绑发起时的工程代际；换工程后旧消息作废。
            let generation = state.borrow().generation;
            let (tx, rx) = std::sync::mpsc::channel();
            state.borrow_mut().render_rx = Some(rx);
            ui.set_ara_progress(0.05);
            ui.set_ara_status("ARA 渲染中…（后台线程）".into());
            ui.set_ara_result("".into());
            let worker_weak = weak.clone();
            let id_for_worker = id.clone();
            std::thread::spawn(move || {
                let mut session = session;
                let message = match crate::plugin_panel::render_taken(
                    &mut session,
                    &id_for_worker,
                    &out_path,
                    block_frames,
                ) {
                    Ok(summary) => AraRenderMessage::Done {
                        generation,
                        id: id_for_worker,
                        session,
                        summary,
                    },
                    Err(error) => AraRenderMessage::Failed {
                        generation,
                        id: id_for_worker,
                        session,
                        error,
                    },
                };
                let _ = tx.send(message);
                let _ = worker_weak.upgrade_in_event_loop(|ui| {
                    ui.invoke_ara_render_drain_requested();
                });
            });
        }
    });

    ui.on_ara_render_drain_requested({
        let weak = weak.clone();
        let state = Rc::clone(&state);
        move || {
            let Some(ui) = weak.upgrade() else {
                return;
            };
            let message = {
                let mut state_borrow = state.borrow_mut();
                let Some(rx) = state_borrow.render_rx.as_ref() else {
                    return;
                };
                match rx.try_recv() {
                    Ok(message) => {
                        state_borrow.render_rx = None;
                        Some(Ok(message))
                    }
                    Err(std::sync::mpsc::TryRecvError::Empty) => None,
                    Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                        state_borrow.render_rx = None;
                        Some(Err(()))
                    }
                }
            };
            // ⭐ T-FIX-349：代际不符 ⇒ 结果属于已关闭工程，直接丢弃（⛔ restore）。
            if let Some(Ok(message)) = &message
                && message.generation() != state.borrow().generation
            {
                return;
            }
            match message {
                Some(Ok(AraRenderMessage::Done {
                    id,
                    session,
                    summary,
                    ..
                })) => {
                    let mut state_borrow = state.borrow_mut();
                    state_borrow.ara.restore(id, session);
                    if let Some(index) = state_borrow.selected_ara
                        && let Some(row) = state_borrow.ara_rows.get_mut(index)
                    {
                        row.state = "渲染完成".to_owned();
                        row.detail = format!(
                            "{} · {} 帧 · {} 字节 · 峰值 {:.4} · 非零 {} 帧",
                            summary.out_path,
                            summary.frames,
                            summary.bytes,
                            summary.peak,
                            summary.nonzero_frames
                        );
                    }
                    ui.set_ara_rows(ModelRc::new(VecModel::from(ara_ui_rows(
                        &state_borrow.ara_rows,
                    ))));
                    ui.set_ara_progress(1.0);
                    ui.set_ara_status(format!("渲染完成：{}", summary.out_path).into());
                    ui.set_ara_result(
                        format!(
                            "{} · {} 帧 · {} 字节 · 峰值 {:.4} · 非零 {} 帧 · blob {} 字节 / {}",
                            summary.out_path,
                            summary.frames,
                            summary.bytes,
                            summary.peak,
                            summary.nonzero_frames,
                            summary.blob_bytes,
                            summary.blob_sha256
                        )
                        .into(),
                    );
                }
                Some(Ok(AraRenderMessage::Failed {
                    id, session, error, ..
                })) => {
                    let mut state_borrow = state.borrow_mut();
                    state_borrow.ara.restore(id, session);
                    if let Some(index) = state_borrow.selected_ara
                        && let Some(row) = state_borrow.ara_rows.get_mut(index)
                    {
                        row.state = "渲染失败".to_owned();
                    }
                    ui.set_ara_rows(ModelRc::new(VecModel::from(ara_ui_rows(
                        &state_borrow.ara_rows,
                    ))));
                    ui.set_ara_progress(0.0);
                    ui.set_ara_status(error.into());
                }
                Some(Err(())) => {
                    ui.set_ara_progress(0.0);
                    ui.set_ara_status("ARA 渲染线程异常结束；会话未恢复".into());
                }
                None => {}
            }
        }
    });
}

// ===========================================================================
// ⭐ T-FIX-208：退出 / 关窗的「未保存改动」保护（数据丢失级）
// ===========================================================================
//
// ## 这一格补的是什么
//
// 「退出 Yeban」与窗口关闭按钮此前都直接 `quit_event_loop()` / 关窗，
// 全仓没有任何工程脏标记 ⇒ 单次误按即可丢掉全部未保存编辑。打开工程那一路
// 有 `saveFirst = true` 保护，退出路径却没有任何等价物 —— 本函数补的正是
// 这条不对称。
//
// ## 判据来自哪里（⛔ 不新造第二份状态）
//
// 「脏不脏」由 `crate::dirty_guard` 用**提交头指针**比对判定：保存成功那一刻
// 记下 `saved_head`，此后 `display().head != saved_head` 即脏。撤销回到保存点
// 头指针相同 ⇒ 自动不脏（这是任何"另设 dirty=true 布尔"都做不到的）。
// 保存成功时的记账在 `wire_save_with_engine` 的 `Saved` 分支里。
//
// ## 三条出口，全部复用既有实现
//
// - 保存并退出：走**同一个** `invoke_save_project()`（与 `save_first_through_the_existing_entry`
//   同款），成功后记账 + 退出；失败留在框里（⛔ 不假装成功）。
// - 直接退出：沿用 app-quit 的原出口（`hide()` + `slint::quit_event_loop()`）。
// - 取消：只关框，工程一位不动。
//
// ## 未安装时零干扰
//
// 判据 / 无头装配若不调本函数，`dirty_guard` 的线程槽为空，`current_is_dirty`
// 恒 false ⇒ app-quit 与窗口关闭行为与改动前逐位一致（既有判据不受影响）。
///
/// 装配退出保护的保存点与三选出口（详见上方模块级说明）。
pub fn wire_quit_guard(ui: &MainWindow, port: &Rc<UndoPort>) {
    // 保存点初值 = 装配这一刻的头：从文件打开的工程此刻就是"已保存"态，
    // 新工程 / 无工程 head 为 None（空基线）—— 两者都不该在启动瞬间就弹框。
    let saved = Rc::new(crate::dirty_guard::SavedHead::new());
    saved.mark_saved(port.display().head);
    crate::dirty_guard::install(Rc::clone(&saved));

    let weak = ui.as_weak();

    // 真正退出：沿用 app-quit 的唯一出口（hide + quit_event_loop）。
    let quit_now = move || {
        let _ = slint::quit_event_loop();
    };

    // ① 保存并退出：复用既有保存入口，成功才退。
    {
        let w = weak.clone();
        let exit = quit_now;
        ui.on_quit_save_and_exit(move || {
            let Some(ui) = w.upgrade() else { return };
            // 与 save_first 同款：先清读数 → 触发那一个保存回调 → 读结果。
            // 保存回调内部（wire_save_with_engine）在 Saved 分支已 mark_saved。
            ui.set_save_succeeded(false);
            ui.set_save_status(slint::SharedString::new());
            ui.invoke_save_project();
            if ui.get_save_succeeded() {
                ui.set_quit_confirm_open(false);
                let _ = ui.window().hide();
                exit();
            } else {
                // 保存失败 / 没落盘：留在框里，响亮给出下一步，⛔ 不假装退出成功。
                let status = ui.get_save_status().to_string();
                ui.set_save_status(
                    format!("{status} · 下一步：先关掉占用工程文件的程序再试，或选「直接退出（放弃改动）」").into(),
                );
            }
        });
    }

    // ② 直接退出（放弃改动）：关框 + 走唯一出口。
    {
        let w = weak.clone();
        let exit = quit_now;
        ui.on_quit_discard_and_exit(move || {
            let Some(ui) = w.upgrade() else { return };
            ui.set_quit_confirm_open(false);
            let _ = ui.window().hide();
            exit();
        });
    }

    // ③ 取消：只关框，工程一位不动。
    {
        let w = weak.clone();
        ui.on_quit_cancel(move || {
            if let Some(ui) = w.upgrade() {
                ui.set_quit_confirm_open(false);
            }
        });
    }

    // ④ 窗口关闭按钮：dirty 时拦下（KeepWindowShown + 弹框），干净时放行。
    //    on_close_requested 必须同步返回，故这里只做"判断 + 弹框"，真正的
    //    退出在三选 callback 里完成（与菜单 app-quit 同一组出口）。
    {
        let w = weak.clone();
        let p = Rc::clone(port);
        ui.window().on_close_requested(move || {
            if let Some(ui) = w.upgrade()
                && crate::dirty_guard::current_is_dirty(p.display().head)
            {
                ui.set_quit_confirm_open(true);
                return slint::CloseRequestResponse::KeepWindowShown;
            }
            slint::CloseRequestResponse::HideWindow
        });
    }
}

#[cfg(test)]
mod sound_library_async_tests {
    use super::*;

    #[test]
    fn installed_scan_generations_drop_stale_results_and_coalesce_running_requests() {
        let state = SoundLibraryAsyncState::default();
        // 首次请求立刻起线程；在飞期间的新请求只登记 pending。
        assert_eq!(state.request_installed(), Some(1));
        assert_eq!(state.request_installed(), None);

        // 旧 generation 完成 ⇒ 不收结果，返回**当前**代号让调用方补扫一次。
        let restart = state.finish_installed(1, Ok(SoundInstalledSnapshot::default()));
        assert_eq!(restart, Some(2), "陈旧结果必须触发一次补扫");
        assert!(
            state.lock().installed_outcome.is_none(),
            "旧 generation 的结果不得进入排空槽"
        );

        // 新 generation 完成 ⇒ 收结果，不再补扫。
        let restart = state.finish_installed(2, Ok(SoundInstalledSnapshot::default()));
        assert_eq!(restart, None);
        let (generation, outcome) = state
            .lock()
            .installed_outcome
            .take()
            .expect("新 generation 必须有结局");
        assert_eq!(generation, 2);
        assert!(outcome.is_ok());
    }

    #[test]
    fn closing_the_panel_invalidates_in_flight_results_without_rescanning() {
        let state = SoundLibraryAsyncState::default();
        assert_eq!(state.request_installed(), Some(1));
        state.cancel_installed();
        assert_eq!(
            state.finish_installed(1, Ok(SoundInstalledSnapshot::default())),
            None,
            "关闭后旧扫描不得补扫"
        );
        assert!(state.lock().installed_outcome.is_none());
        assert!(!state.lock().installed_in_flight);
    }
}

/// ⭐ **T-FIX-489**：复制 / 切分不再把 `fade_in_ticks` / `fade_out_ticks` 静默清零。
///
/// 粘贴那一处需要 `MainWindow`（选中轨与播放头），本机编不了 Slint ⇒ 行为交 CI；
/// 这里用**源码纪律**钉住"粘贴继承剪贴板淡值"，其余两处直接喂合成工程逐字段对账。
#[cfg(test)]
mod clip_fade_carry_tests {
    use super::{clip_split_ops_for, duplicate_clip_placement_ops_for};
    use yeban_model::ops::Op;
    use yeban_model::{EntityId, YebanProjectV1};

    /// 演示工程里 Lead 轨那条 3840 tick 的摆放（唯一稳定的假体）。
    fn fixture() -> (YebanProjectV1, EntityId, EntityId) {
        let project = yeban_model::samples::demo_project();
        let (track_id, placement_id) = project
            .tracks
            .iter()
            .filter(|(id, track)| **id != project.master_bus_track_id && !track.clips.is_empty())
            .find_map(|(id, track)| track.clips.keys().next().map(|placement| (*id, *placement)))
            .expect("演示工程必须有非主总线轨道且带摆放");
        (project, track_id, placement_id)
    }

    fn set_fades(
        project: &mut YebanProjectV1,
        track_id: EntityId,
        placement_id: EntityId,
        fade_in: Option<u64>,
        fade_out: Option<u64>,
    ) {
        let placement = project
            .tracks
            .get_mut(&track_id)
            .expect("轨道")
            .clips
            .get_mut(&placement_id)
            .expect("摆放");
        placement.fade_in_ticks = fade_in;
        placement.fade_out_ticks = fade_out;
    }

    fn set_span(
        project: &mut YebanProjectV1,
        track_id: EntityId,
        placement_id: EntityId,
        start_tick: u64,
        duration_ticks: u64,
    ) {
        let placement = project
            .tracks
            .get_mut(&track_id)
            .expect("轨道")
            .clips
            .get_mut(&placement_id)
            .expect("摆放");
        placement.start_tick = start_tick;
        placement.duration_ticks = duration_ticks;
    }

    /// ① 复制：`fade_in = 10 / fade_out = 20` 的摆放，复制件逐字段继承。
    #[test]
    fn duplicate_carries_both_fades() {
        let (mut project, track_id, placement_id) = fixture();
        set_fades(&mut project, track_id, placement_id, Some(10), Some(20));
        let (ops, new_id) = duplicate_clip_placement_ops_for(&project, &placement_id.to_string())
            .expect("复制必须成立");
        for op in &ops {
            op.apply(&mut project).expect("复制 op 必须能应用");
        }
        let copy = project
            .tracks
            .get(&track_id)
            .expect("轨道")
            .clips
            .get(&new_id.parse::<EntityId>().expect("新摆放身份"))
            .expect("复制件必须存在");
        assert_eq!(copy.fade_in_ticks, Some(10), "复制件必须继承淡入");
        assert_eq!(copy.fade_out_ticks, Some(20), "复制件必须继承淡出");
    }

    /// ② 切分：100 tick 摆放、`fade_out = 100`，在 50 tick 处切开 ——
    /// 左半先收窄淡值再缩长度（整批 `apply` 必须一次过），任一半都不得留下
    /// `fade_out > 本半长度`；切点两侧的淡值按"淡出不跨切点"重分配。
    #[test]
    fn split_redistributes_the_end_fade_into_the_right_half() {
        let (mut project, track_id, placement_id) = fixture();
        set_span(&mut project, track_id, placement_id, 0, 100);
        set_fades(&mut project, track_id, placement_id, None, Some(100));
        let (ops, right_id) =
            clip_split_ops_for(&project, &placement_id.to_string(), 50).expect("切分必须成立");
        assert!(
            matches!(ops.first(), Some(Op::SetClipPlacementFade { .. })),
            "左半必须先发淡值 op：顺序反了会被 `SetClipPlacementDuration` 的新前置条件拒收"
        );
        for op in &ops {
            op.apply(&mut project)
                .unwrap_or_else(|error| panic!("切分批必须能按序应用: {error:?}"));
        }
        let right_id = right_id.parse::<EntityId>().expect("右半身份");
        let track = project.tracks.get(&track_id).expect("轨道");
        let left = track.clips.get(&placement_id).expect("左半");
        let right = track.clips.get(&right_id).expect("右半");
        assert_eq!(left.duration_ticks, 50, "左半缩到切点");
        assert!(
            left.fade_out_ticks.unwrap_or(0) <= 50,
            "左半不得留下超过新长度的淡出: {:?}",
            left.fade_out_ticks
        );
        assert_eq!(
            right.fade_out_ticks,
            Some(50),
            "右半继承末端淡出并收窄到 50"
        );
        assert_eq!(right.fade_in_ticks, None, "切点是硬起点");
    }

    /// ③ 切分：`fade_in = 100` 的 100 tick 摆放，切在 20 tick —— 左半淡入收窄到 20。
    #[test]
    fn split_clamps_the_start_fade_inside_the_left_half() {
        let (mut project, track_id, placement_id) = fixture();
        set_span(&mut project, track_id, placement_id, 0, 100);
        set_fades(&mut project, track_id, placement_id, Some(100), None);
        let (ops, right_id) =
            clip_split_ops_for(&project, &placement_id.to_string(), 20).expect("切分必须成立");
        for op in &ops {
            op.apply(&mut project).expect("切分批必须能按序应用");
        }
        let right_id = right_id.parse::<EntityId>().expect("右半身份");
        let track = project.tracks.get(&track_id).expect("轨道");
        let left = track.clips.get(&placement_id).expect("左半");
        let right = track.clips.get(&right_id).expect("右半");
        assert_eq!(left.fade_in_ticks, Some(20), "左半淡入收窄到 20");
        assert_eq!(left.fade_out_ticks, None);
        assert_eq!(right.fade_in_ticks, None, "切点是硬起点");
        assert_eq!(right.fade_out_ticks, None);
    }

    /// ④ 粘贴：剪贴板条目带着 `fade_in = 10 / fade_out = 20` ⇒ 新摆放逐字段一致。
    #[test]
    fn paste_carries_both_fades_from_the_clipboard_entry() {
        let (mut project, track_id, placement_id) = fixture();
        set_fades(&mut project, track_id, placement_id, Some(10), Some(20));
        let placement = project.tracks[&track_id].clips[&placement_id];
        let entry = project
            .clip_pool
            .get(&placement.clip_id)
            .expect("片段池条目")
            .clone();
        let (ops, new_id) =
            super::clipboard_paste_ops_for_entry(&entry, &placement, track_id, 3840);
        for op in &ops {
            op.apply(&mut project).expect("粘贴 op 必须能应用");
        }
        let pasted = project.tracks[&track_id].clips[&new_id];
        assert_eq!(pasted.fade_in_ticks, Some(10), "粘贴件必须继承淡入");
        assert_eq!(pasted.fade_out_ticks, Some(20), "粘贴件必须继承淡出");
        assert_eq!(pasted.start_tick, 3840, "粘贴落在给定起点");
    }

    /// ⑤ 源码纪律：三处构造点不许再写死 `None`，粘贴必须继承剪贴板里的两个淡值。
    #[test]
    fn no_construction_site_zeroes_the_fades_any_more() {
        let source = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/src/host.rs"))
            .expect("读取 host.rs");
        assert!(
            source.contains("fade_in_ticks: base.fade_in_ticks"),
            "粘贴必须继承剪贴板淡入"
        );
        assert!(
            source.contains("fade_out_ticks: base.fade_out_ticks"),
            "粘贴必须继承剪贴板淡出"
        );
        assert!(
            source.contains("fade_in_ticks: placement.fade_in_ticks")
                && source.contains("fade_out_ticks: placement.fade_out_ticks"),
            "复制必须继承原摆放两个淡值"
        );
    }
}
